/* Zain Kaka · supplied Renal & GIT question bank; educational practice. Difficulty is editorial (3 applied, 4 hard, 5 extreme). */
window.MED_P2_KAKAMED=[{"id":94001,"title":"A toddler with swelling and poor growth","core":["Severe Acute Malnutrition"],"module":"GIT","scenario":"A 20-month-old child is brought to clinic because of poor appetite, intermittent loose stools and swelling of both feet. His mother has been relying on maize porridge since losing her job. He is apathetic, with sparse discoloured hair, loss of muscle bulk, patchy peeling skin and bilateral pitting oedema extending to the knees. His weight appears relatively preserved. He feels cool and has no obvious fever.","labContext":"MUAC (mm): 112  (Reference: ≥125 (6–59 months); \u003c115 severe)\nTemperature (°C): 35.4  (Reference: 36.5–37.5)\nGlucose (mmol/L): 2.6  (Reference: 3.9–7.8 (illustrative))\nAlbumin (g/L): 19  (Reference: 35–50)","difficulty":"Challenge","difficultyRating":3,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Guide pp. 344; GIT notes nutrition themes pp. 236–238; SV GIT nutrition","questions":[{"number":1,"q":"Which finding independently establishes severe acute malnutrition in this age group despite apparently preserved weight?","type":"SBA","options":["Reduced appetite with loose stools","Reduced weight gain with muscle wasting","Bilateral nutritional pitting oedema","Sparse hair with pigment loss"],"answer":"C","whyOptions":["Important complications but not diagnostic alone.","Requires objective anthropometry or qualifying oedema.","Oedema can mask weight loss; bilateral nutritional oedema establishes SAM after other causes are considered.","Supportive, not an independent diagnostic criterion."],"explain":"Oedema can mask weight loss; bilateral nutritional oedema establishes SAM after other causes are considered."},{"number":2,"q":"Which mechanism contributes to swelling in this child?","type":"SBA","options":["Reduced capillary filtration with isolated arterial vasoconstriction","Increased plasma oncotic pressure with renal salt loss","Increased lymphatic drainage with reduced interstitial protein","Reduced plasma oncotic pressure with altered fluid regulation"],"answer":"D","whyOptions":["Does not account for generalized oedema.","Increased oncotic pressure opposes oedema.","Would oppose tissue fluid accumulation.","Low albumin and disturbed cellular/vascular homeostasis contribute to oedema; the mechanism is multifactorial."],"explain":"Low albumin and disturbed cellular/vascular homeostasis contribute to oedema; the mechanism is multifactorial."},{"number":3,"q":"Why is the absence of fever not reassuring in this child?","type":"SBA","options":["Impaired immune responses may mask serious infection","Low albumin prevents microbial replication","Loss of adipose tissue prevents bacterial invasion","Reduced appetite indicates a sterile inflammatory response"],"answer":"A","whyOptions":["Malnutrition impairs innate and adaptive immune responses.","Hypoalbuminaemia is not protective.","Fat loss does not prevent infection.","Anorexia occurs in both infection and malnutrition."],"explain":"Malnutrition impairs innate and adaptive immune responses."},{"number":4,"q":"After feeding is restarted, which intracellular electrolyte shift raises concern for refeeding syndrome?","type":"SBA","options":["Aldosterone-mediated phosphate retention in proximal tubules","Insulin-mediated phosphate release from cells","Glucagon-mediated release of phosphate from cells","Insulin-mediated uptake of phosphate into cells"],"answer":"D","whyOptions":["Not the primary refeeding mechanism.","Insulin drives uptake, not release.","Would tend to increase serum phosphate.","Anabolism consumes phosphate; potassium and magnesium may also fall."],"explain":"Anabolism consumes phosphate; potassium and magnesium may also fall."},{"number":5,"q":"Which supervised initial approach is safest given his temperature and glucose?","type":"SBA","options":["Routine rapid IV fluid boluses for oedema alone","Immediate unrestricted high-protein feeding and routine discharge","Urgent glucose correction, warming and SAM-specific stabilisation","Diuretic treatment followed by delayed feeding"],"answer":"C","whyOptions":["SAM requires cautious assessment of hydration; fluid overload is dangerous.","Rapid feeding risks metabolic complications and ignores instability.","Hypoglycaemia and hypothermia are danger signs; careful feeding and infection assessment are essential.","Nutritional oedema is not a routine indication for diuretics."],"explain":"Hypoglycaemia and hypothermia are danger signs; careful feeding and infection assessment are essential."},{"number":6,"q":"Which pattern indicates a need for close monitoring during nutritional rehabilitation?","context":"Repeat results after assessment:\nPhosphate (mmol/L): 0.48  (Reference: 1.3–2.1 (age-specific illustrative))\nPotassium (mmol/L): 2.9  (Reference: 3.5–5.1)\nMagnesium (mmol/L): 0.57  (Reference: 0.70–1.00)","isData":true,"type":"SBA","options":["Depleted electrolytes with increased risk of refeeding complications","Hyperosmolar dehydration with elevated circulating electrolytes","Primary renal phosphate retention with secondary hyperkalaemia","Isolated albumin loss with preserved intracellular mineral stores"],"answer":"A","whyOptions":["Phosphate, potassium and magnesium depletion can worsen with feeding.","The listed findings do not show this.","Both phosphate and potassium are low.","The measured electrolytes are depleted."],"explain":"Phosphate, potassium and magnesium depletion can worsen with feeding."},{"number":7,"q":"Which anthropometric measurement uses a tape placed around the upper arm?","type":"VSAQ","options":[],"answer":"Mid-upper arm circumference","accepted":["MUAC","mid upper arm circumference"],"explain":"MUAC is a rapid screening and diagnostic measure for wasting in children aged 6–59 months."},{"number":8,"q":"Which initial therapeutic milk is used during the stabilisation phase of complicated SAM?","type":"VSAQ","options":[],"answer":"F-75","accepted":["F75"],"explain":"F-75 is formulated for cautious stabilisation before catch-up feeding."}]},{"id":94002,"title":"An infant with vomiting and watery stools","core":["Acute Gastroenteritis"],"module":"GIT","scenario":"An 11-month-old boy develops vomiting and frequent watery stools after several children at his crèche became ill. He has missed some routine immunisations. His eyes are sunken and he drinks eagerly. Skin pinch returns slowly; he is alert and has a warm periphery. There is no blood in the stool.","labContext":"Heart rate (/min): 138  (Reference: 100–160 (age-specific))\nTemperature (°C): 37.8  (Reference: 36.5–37.5)\nSodium (mmol/L): 137  (Reference: 135–145)\nBicarbonate (mmol/L): 17  (Reference: 22–26)","difficulty":"Challenge","difficultyRating":3,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Guide pp. 345; GIT notes pp. 239–272; 2026 GEMP 2 Cases pp. 2–3","questions":[{"number":1,"q":"Which mechanism best explains watery stools in rotavirus infection?","type":"SBA","options":["Villous enterocyte injury with impaired absorption and secretory effects","Deep colonic invasion with crypt abscess formation","Isolated pancreatic acinar destruction with lipase deficiency","Preformed toxin ingestion with no intestinal infection"],"answer":"A","whyOptions":["Rotavirus damages mature enterocytes; NSP4 contributes to secretion.","More typical of inflammatory colitis.","Produces fat maldigestion rather than acute viral diarrhoea.","Typical of short-incubation food intoxication."],"explain":"Rotavirus damages mature enterocytes; NSP4 contributes to secretion."},{"number":2,"q":"Which transport mechanism permits oral rehydration despite ongoing diarrhoea?","type":"SBA","options":["Apical chloride secretion driven by cyclic AMP","Apical glucose diffusion independent of sodium","Basolateral sodium entry through ENaC","Apical sodium–glucose cotransport using the sodium gradient"],"answer":"D","whyOptions":["Promotes secretion, not absorption.","Does not explain coupled sodium uptake.","Not the principal intestinal ORS mechanism.","SGLT1 supports solute and water absorption."],"explain":"SGLT1 supports solute and water absorption."},{"number":3,"q":"Which acid–base mechanism most directly explains reduced bicarbonate?","type":"SBA","options":["Increased renal bicarbonate generation","Primary alveolar hypoventilation","Gastric hydrochloric acid loss in stool","Gastrointestinal bicarbonate loss in stool"],"answer":"D","whyOptions":["Would compensate rather than cause acidosis.","Causes respiratory acidosis.","Acid loss favours alkalosis.","Diarrhoea can cause normal-anion-gap metabolic acidosis."],"explain":"Diarrhoea can cause normal-anion-gap metabolic acidosis."},{"number":4,"q":"Which action best reduces further transmission in the crèche?","type":"SBA","options":["Stool culture clearance for every asymptomatic child","Restrict feeding of all exposed children","Hand hygiene, safe nappy handling and appropriate notification","Empirical antibiotics for asymptomatic contacts"],"answer":"C","whyOptions":["Not generally needed.","Does not prevent spread and risks nutritional harm.","Faecal–oral prevention addresses transmission; vaccination reduces severe rotavirus disease.","Not indicated for routine viral exposure."],"explain":"Faecal–oral prevention addresses transmission; vaccination reduces severe rotavirus disease."},{"number":5,"q":"He remains alert and able to drink. What initial supervised approach fits this hydration assessment?","type":"SBA","options":["Oral antimotility medication as the primary intervention","Withhold feeds until stools become formed","Oral rehydration with reassessment and continued feeding","IV fluid resuscitation for every watery stool"],"answer":"C","whyOptions":["Unsafe in young children and does not replace fluid.","Continued feeding supports recovery.","Some dehydration with drinking ability is generally managed with ORS and close reassessment.","Not necessary in the absence of shock or inability to drink."],"explain":"Some dehydration with drinking ability is generally managed with ORS and close reassessment."},{"number":6,"q":"Which interpretation changes the immediate management?","context":"Four hours later:\nCapillary refill (s): 4  (Reference: ≤2)\nHeart rate (/min): 178  (Reference: 100–160)\nMental state: Lethargic, unable to drink  (Reference: Alert, drinks)\nUrine output (mL/kg/h): 0.2  (Reference: Generally ≥1 in infants)","isData":true,"type":"SBA","options":["Isolated electrolyte disturbance without circulatory compromise","Expected recovery with transient tachycardia","Severe dehydration with impaired perfusion requiring urgent escalation","Mild dehydration with preserved oral intake"],"answer":"C","whyOptions":["Capillary refill and mental state indicate circulatory risk.","The signs indicate deterioration.","New lethargy, poor perfusion and inability to drink require urgent supervised resuscitation.","Oral intake and perfusion are no longer preserved."],"explain":"New lethargy, poor perfusion and inability to drink require urgent supervised resuscitation."},{"number":7,"q":"Which transporter is directly exploited by glucose-containing ORS?","type":"VSAQ","options":[],"answer":"SGLT1","accepted":["SGLT-1","sodium glucose cotransporter 1"],"explain":"The apical sodium–glucose cotransporter enables absorption despite many secretory diarrhoeal illnesses."},{"number":8,"q":"What type of immunity is induced by rotavirus vaccination?","type":"VSAQ","options":[],"answer":"Active immunity","accepted":["active acquired immunity","artificial active immunity"],"explain":"Vaccination stimulates the recipient's own adaptive immune response."}]},{"id":94003,"title":"Loose stools that stop with fasting","core":["Diarrhoea"],"module":"GIT","scenario":"A 29-year-old woman reports watery stools and bloating after consuming large quantities of sugar-free sweets containing sorbitol. The stools improve overnight when she does not eat. She has no blood, fever, weight loss or nocturnal symptoms. Examination is unremarkable apart from mild dehydration.","labContext":"Sodium (mmol/L): 139  (Reference: 135–145)\nPotassium (mmol/L): 3.4  (Reference: 3.5–5.1)\nChloride (mmol/L): 110  (Reference: 98–107)\nBicarbonate (mmol/L): 19  (Reference: 22–26)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 23, 30–31, 123–138; Guide p. 346; SV GIT diarrhoea physiology","questions":[{"number":1,"q":"Which mechanism explains improvement with fasting?","type":"SBA","options":["Accelerated pancreatic proteolysis produces mucosal injury","Persistent chloride secretion independent of luminal substrate","Mucosal invasion produces inflammatory exudate","Retained poorly absorbed solutes draw water into the lumen"],"answer":"D","whyOptions":["Not characteristic of sorbitol exposure.","Secretory diarrhoea tends to persist during fasting.","Often associated with blood or systemic inflammation.","Removal of osmotic substrate reduces diarrhoea."],"explain":"Removal of osmotic substrate reduces diarrhoea."},{"number":2,"q":"Which acid–base pattern is most consistent with the electrolytes?","type":"SBA","options":["Chloride-depletion metabolic alkalosis from gastric losses","Normal-anion-gap metabolic acidosis from stool bicarbonate loss","Respiratory alkalosis with no metabolic component","High-anion-gap acidosis from retained organic acids"],"answer":"B","whyOptions":["Bicarbonate is reduced, chloride increased.","139 − 110 − 19 = 10 mmol/L; chloride rises as bicarbonate falls.","No blood gas establishes this, and stool losses explain the metabolic pattern.","The calculated gap is not raised."],"explain":"139 − 110 − 19 = 10 mmol/L; chloride rises as bicarbonate falls."},{"number":3,"q":"Which mechanism contributes to hypokalaemia?","type":"SBA","options":["Reduced distal sodium delivery with excessive potassium retention","Faecal potassium loss with possible secondary aldosterone activation","Increased cellular potassium release due to tissue destruction","Reduced aldosterone with increased collecting duct secretion"],"answer":"B","whyOptions":["Would oppose hypokalaemia.","GI losses and volume contraction contribute.","Raises serum potassium.","Low aldosterone reduces potassium secretion."],"explain":"GI losses and volume contraction contribute."},{"number":4,"q":"Which change would most strongly suggest an inflammatory rather than osmotic process?","type":"SBA","options":["New bloody nocturnal stools with raised inflammatory markers","Normal examination between episodes","Relief after fasting with bloating","Reproducible symptoms after sorbitol ingestion"],"answer":"A","whyOptions":["These are alarm features suggesting organic inflammation.","Does not favour inflammation.","Supports osmotic diarrhoea.","Supports osmotic diarrhoea."],"explain":"These are alarm features suggesting organic inflammation."},{"number":5,"q":"Which initial advice is most appropriate in this stable patient?","type":"SBA","options":["Eliminate all carbohydrate sources permanently","Begin empirical antibiotics before dietary assessment","Begin long-term opioid antimotility therapy","Remove the suspected osmotic trigger, rehydrate and reassess persistent symptoms"],"answer":"D","whyOptions":["Unnecessarily restrictive.","No evidence of invasive infection.","Does not address the trigger.","Cause-directed advice with safety netting is appropriate."],"explain":"Cause-directed advice with safety netting is appropriate."},{"number":6,"q":"Which calculated result supports the suspected mechanism? Use 290 − 2(Na + K).","context":"Stool electrolytes obtained during symptoms; assumed stool osmolality 290 mOsm/kg.\nStool Na (mmol/L): 32  (Reference: Variable)\nStool K (mmol/L): 28  (Reference: Variable)\nCalculated osmotic gap (mOsm/kg): ?   (Reference: >100 supports osmotic; \u003c50 secretory)","isData":true,"type":"SBA","options":["60 mOsm/kg, supporting a secretory mechanism","120 mOsm/kg, supporting a secretory mechanism","170 mOsm/kg, supporting an osmotic mechanism","230 mOsm/kg, supporting inflammatory exudation"],"answer":"C","whyOptions":["60 is the unmultiplied electrolyte sum.","120 is the estimated electrolyte contribution, not the gap.","290 − 2(32+28) = 170.","This subtracts the electrolyte sum only once."],"explain":"290 − 2(32+28) = 170."},{"number":7,"q":"Name the acid–base disorder caused by loss of bicarbonate-rich intestinal fluid.","type":"VSAQ","options":[],"answer":"Metabolic acidosis","accepted":["normal anion gap metabolic acidosis","hyperchloraemic metabolic acidosis","hyperchloremic metabolic acidosis"],"explain":"Bicarbonate loss is replaced by chloride, maintaining electroneutrality."},{"number":8,"q":"Which intestinal process produces gas from unabsorbed carbohydrates?","type":"VSAQ","options":[],"answer":"Bacterial fermentation","accepted":["colonic fermentation","fermentation"],"explain":"Colonic bacteria metabolise carbohydrates, generating gas and short-chain fatty acids."}]},{"id":94004,"title":"Vomiting after a community meal","core":["Food Poisoning"],"module":"GIT","scenario":"A 36-year-old woman and several relatives develop sudden vomiting and abdominal cramps three hours after eating sandwiches prepared in advance for a church event. She has little diarrhoea, no fever and no blood in stool. The food had been left unrefrigerated. Her symptoms begin to settle within a day.","labContext":"Heart rate (/min): 102  (Reference: 60–100)\nTemperature (°C): 36.9  (Reference: 36.5–37.5)\nPotassium (mmol/L): 3.4  (Reference: 3.5–5.1)\nCRP (mg/L): 4  (Reference: \u003c5)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 239–272; combined GIT bank cluster 11; Guide p. 347","questions":[{"number":1,"q":"Which mechanism best explains the short incubation?","type":"SBA","options":["Ingestion of preformed enterotoxin in food","Bacterial invasion followed by mucosal ulceration","Viral replication with delayed villous damage","Protozoal excystation with progressive malabsorption"],"answer":"A","whyOptions":["A toxin already present can act rapidly without bacterial replication in the host.","Usually needs more time and produces inflammatory symptoms.","Typical viral gastroenteritis generally incubates longer.","Usually causes a longer incubation and prolonged symptoms."],"explain":"A toxin already present can act rapidly without bacterial replication in the host."},{"number":2,"q":"Which organism is particularly associated with handled food and rapid emetic intoxication?","type":"SBA","options":["Staphylococcus aureus","Campylobacter jejuni","Giardia duodenalis","Shigella sonnei"],"answer":"A","whyOptions":["Preformed heat-stable enterotoxin causes abrupt vomiting.","Invasive enteritis, often febrile or bloody.","Persistent malabsorptive diarrhoea.","Typically inflammatory diarrhoea with a longer incubation."],"explain":"Preformed heat-stable enterotoxin causes abrupt vomiting."},{"number":3,"q":"Why may reheating the contaminated food fail to prevent illness?","type":"SBA","options":["Heat creates a new viral infection in food","Heat-stable toxin may persist despite killing vegetative bacteria","Spores of staphylococci germinate in the stomach","Reheating increases bacterial invasion of the intestine"],"answer":"B","whyOptions":["Viruses do not originate from heating.","Some staphylococcal enterotoxins resist ordinary cooking.","Staphylococci are not spore-forming.","Invasion is not the principal mechanism."],"explain":"Some staphylococcal enterotoxins resist ordinary cooking."},{"number":4,"q":"What treatment principle is appropriate for this stable toxin-mediated presentation?","type":"SBA","options":["Long-term corticosteroids to suppress colitis","Antibiotics to neutralise circulating enterotoxin","Immediate endoscopy to remove residual toxin","Fluid and electrolyte replacement with monitoring"],"answer":"D","whyOptions":["No evidence of autoimmune inflammation.","Antibiotics do not neutralise preformed toxin.","Not routinely indicated.","Supportive treatment is usually sufficient."],"explain":"Supportive treatment is usually sufficient."},{"number":5,"q":"Which public-health action best helps identify the food responsible?","type":"SBA","options":["Interview exposed and unexposed attendees using a common case definition","Interview only hospitalised attendees about their favourite food","Count only cases with positive blood cultures","Culture every food handler without obtaining exposure histories"],"answer":"A","whyOptions":["Comparative exposure data help identify the vehicle.","Selection bias and no comparison group.","Toxin-mediated illness need not produce bacteraemia.","May miss the actual epidemiological link."],"explain":"Comparative exposure data help identify the vehicle."},{"number":6,"q":"Which comparison most strongly supports the suspected food vehicle?","context":"Outbreak investigation:\nAte sandwiches: ill/total: 36/48  (Reference: Not applicable)\nDid not eat sandwiches: ill/total: 4/32  (Reference: Not applicable)","isData":true,"type":"SBA","options":["Attack rates 36% versus 4%, risk ratio 9","Attack rates 45% versus 5%, risk ratio 9","Attack rates 48% versus 32%, risk ratio 1.5","Attack rates 75% versus 12.5%, risk ratio 6"],"answer":"D","whyOptions":["Counts are not percentages without denominators.","Uses total attendance for both exposure groups.","Uses exposed group sizes rather than cases.","36/48 = .75; 4/32 = .125; ratio 6."],"explain":"36/48 = .75; 4/32 = .125; ratio 6."},{"number":7,"q":"What epidemiological measure is the proportion of exposed people who become ill?","type":"VSAQ","options":[],"answer":"Attack rate","accepted":["attack proportion"],"explain":"An attack rate compares new cases with the population at risk during an outbreak."},{"number":8,"q":"Name the other classical preformed emetic toxin-producing bacterium associated with improperly stored rice.","type":"VSAQ","options":[],"answer":"Bacillus cereus","accepted":["B cereus"],"explain":"The emetic form of B. cereus food poisoning results from preformed cereulide."}]},{"id":94005,"title":"Fever and frequent small bloody stools","core":["Shigellosis"],"module":"GIT","scenario":"A 5-year-old child presents with fever, cramps, and frequent small-volume stools containing blood and mucus. He repeatedly strains even when little stool passes. His siblings share a crowded household with limited access to running water. He is thirsty but alert.","labContext":"Temperature (°C): 39.0  (Reference: 36.5–37.5)\nWCC (×10⁹/L): 16.2  (Reference: 5–15 (illustrative age range))\nCRP (mg/L): 74  (Reference: \u003c5)\nCreatinine (µmol/L): 36  (Reference: 20–50 (age-specific))","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Distinction Expanded pp. 17–21; Seven Core pp. 8–9; Guide p. 348","questions":[{"number":1,"q":"Which pathological process best accounts for blood, mucus and tenesmus?","type":"SBA","options":["Pancreatic enzyme deficiency with retained luminal fat","Invasion of colonic epithelium with neutrophilic mucosal inflammation","Toxin-mediated small bowel chloride secretion without mucosal injury","Duodenal protozoal adhesion with brush-border dysfunction"],"answer":"B","whyOptions":["Produces steatorrhoea.","Shigella invades the colonic mucosa, producing dysentery and rectal urgency.","Produces profuse watery diarrhoea rather than dysentery.","Produces malabsorption, usually without blood."],"explain":"Shigella invades the colonic mucosa, producing dysentery and rectal urgency."},{"number":2,"q":"Which bacterial property contributes to person-to-person transmission?","type":"SBA","options":["Formation of airborne endospores","Dependence on an intermediate aquatic host","Low infectious dose with relative acid resistance","Obligatory growth in an insect vector"],"answer":"C","whyOptions":["Shigella is non-spore-forming.","Shigella is transmitted faecal–orally without an intermediate host.","Few organisms can initiate infection after ingestion.","Not part of its transmission cycle."],"explain":"Few organisms can initiate infection after ingestion."},{"number":3,"q":"Which cellular target explains the action of Shiga toxin when present?","type":"SBA","options":["Gs alpha subunit of adenylate cyclase","28S rRNA of the 60S ribosomal subunit","Guanylate cyclase C on enterocytes","Voltage-gated sodium channels of motor neurons"],"answer":"B","whyOptions":["Cholera toxin activates this pathway.","Toxin inhibits protein synthesis and can injure vascular endothelium.","Heat-stable ETEC toxin activates this pathway.","Not the mechanism of Shiga toxin."],"explain":"Toxin inhibits protein synthesis and can injure vascular endothelium."},{"number":4,"q":"Which initial investigation best supports pathogen-directed antibiotic selection in this child?","type":"SBA","options":["Serum antibody titre for previous enteric exposure","Faecal elastase concentration","Stool culture with susceptibility testing","Routine colonoscopy with mucosal biopsy"],"answer":"C","whyOptions":["Does not establish active infection or susceptibility.","Tests pancreatic exocrine function.","Resistance matters; obtain appropriate specimens without delaying necessary care.","Not the initial investigation in acute infectious dysentery."],"explain":"Resistance matters; obtain appropriate specimens without delaying necessary care."},{"number":5,"q":"Which action best addresses both child safety and community risk?","type":"SBA","options":["Assess hydration, escalate for dysentery treatment and reinforce hand hygiene","Delay rehydration until organism identification","Use loperamide to reduce stool frequency before assessment","Treat all household contacts empirically without assessment"],"answer":"A","whyOptions":["Bloody diarrhoea needs assessment, appropriate antimicrobials when indicated and prevention.","Hydration should not wait.","Antimotility drugs may be harmful in invasive diarrhoea.","Routine indiscriminate antibiotic use is inappropriate."],"explain":"Bloody diarrhoea needs assessment, appropriate antimicrobials when indicated and prevention."},{"number":6,"q":"Which complication is suggested by this new triad?","context":"Four days later, the child deteriorates:\nHb (g/dL): 7.7  (Reference: 11.5–15.5)\nPlatelets (×10⁹/L): 54  (Reference: 150–400)\nCreatinine (µmol/L): 132  (Reference: 20–50)\nBlood film: Schistocytes  (Reference: Absent)","isData":true,"type":"SBA","options":["Immune thrombocytopenia with incidental dehydration","Isolated postinfectious glomerulonephritis","Iron deficiency with reduced platelet production","Haemolytic uraemic syndrome with microangiopathic injury"],"answer":"D","whyOptions":["Does not explain microangiopathic haemolysis.","Does not typically produce schistocytes and severe thrombocytopenia.","Does not explain acute AKI and fragmentation.","Haemolysis, thrombocytopenia and AKI suggest HUS, classically associated with Shiga toxin."],"explain":"Haemolysis, thrombocytopenia and AKI suggest HUS, classically associated with Shiga toxin."},{"number":7,"q":"Which type of intestinal epithelial cell is exploited by Shigella to cross the follicle-associated epithelium?","type":"VSAQ","options":[],"answer":"M cell","accepted":["M cells","microfold cell","microfold cells"],"explain":"M cells sample luminal material and can provide a route for Shigella entry."},{"number":8,"q":"What clinical term describes painful straining with persistent sensation of needing to pass stool?","type":"VSAQ","options":[],"answer":"Tenesmus","accepted":[],"explain":"Rectal inflammation triggers tenesmus."}]},{"id":94006,"title":"Persistent diarrhoea after a camping trip","core":["Giardiasis"],"module":"GIT","scenario":"A 24-year-old man develops bloating, foul-smelling floating stools and weight loss after drinking stream water on a hiking trip. Symptoms persist for four weeks. He reports worsening symptoms after milk. There is no fever or visible blood. He has mild abdominal distension and no guarding.","labContext":"Albumin (g/L): 32  (Reference: 35–50)\nCRP (mg/L): 3  (Reference: \u003c5)\nHb (g/dL): 13.4  (Reference: 13–17)\nPotassium (mmol/L): 3.4  (Reference: 3.5–5.1)","difficulty":"Challenge","difficultyRating":3,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Distinction Expanded pp. 2–6; Seven Core pp. 2–3; Guide p. 349","questions":[{"number":1,"q":"Which process most directly explains the greasy stools?","type":"SBA","options":["Proximal small bowel brush-border dysfunction following protozoal attachment","Colonic mucosal invasion with neutrophilic ulceration","Bile duct obstruction reducing intestinal bile salts","Pancreatic duct obstruction causing reduced bicarbonate secretion"],"answer":"A","whyOptions":["Giardia impairs nutrient absorption without extensive invasion.","Produces inflammatory dysentery.","Would often cause cholestatic signs and biochemistry.","Possible malabsorption differential, but water exposure and bloating favour Giardia."],"explain":"Giardia impairs nutrient absorption without extensive invasion."},{"number":2,"q":"Which form survives outside the host and initiates infection?","type":"SBA","options":["Motile trophozoite","Mature cyst","Encysted larva","Sporulated oocyst"],"answer":"B","whyOptions":["Feeding form, less resistant outside the host.","Cysts are environmentally hardy and infective on ingestion.","A helminth stage, not Giardia.","Characteristic of other protozoa, not Giardia."],"explain":"Cysts are environmentally hardy and infective on ingestion."},{"number":3,"q":"Which mechanism explains his new milk intolerance?","type":"SBA","options":["Reduced bile salt secretion causing lactose precipitation","Increased lactase activity causing colonic carbohydrate retention","Reduced pancreatic amylase causing lactose maldigestion","Loss of brush-border lactase causing osmotic retention of lactose"],"answer":"D","whyOptions":["Bile salts aid lipid digestion, not lactose hydrolysis.","Would increase digestion.","Lactose requires lactase, not amylase.","Unabsorbed lactose is fermented in the colon."],"explain":"Unabsorbed lactose is fermented in the colon."},{"number":4,"q":"Which mucosal immune component assists clearance and may be deficient in recurrent disease?","type":"SBA","options":["Plasma fibrinogen","Secretory IgA","Erythrocyte-bound IgG","Circulating IgE"],"answer":"B","whyOptions":["Coagulation protein, not mucosal antibody.","Mucosal IgA helps limit attachment and infection.","Not a major mucosal defence mechanism.","Mainly associated with allergy and helminth responses."],"explain":"Mucosal IgA helps limit attachment and infection."},{"number":5,"q":"Which investigation and treatment approach is appropriate?","type":"SBA","options":["Single negative microscopy followed by definitive exclusion","Empirical prolonged antibacterial therapy with no reassessment","Pancreatic enzyme replacement without stool evaluation","Stool antigen or microscopy with appropriate antiprotozoal therapy and hydration"],"answer":"D","whyOptions":["Intermittent shedding limits sensitivity.","Not appropriate for confirmed protozoal disease.","Does not address the likely infection.","Intermittent shedding can require repeat specimens; metronidazole is a common option."],"explain":"Intermittent shedding can require repeat specimens; metronidazole is a common option."},{"number":6,"q":"Which interpretation best integrates these findings?","context":"Stool testing:\nGiardia antigen: Positive  (Reference: Negative)\nFaecal elastase (µg/g): 390  (Reference: >200)\nFaecal fat (g/day): 14  (Reference: \u003c7 with adequate intake)","isData":true,"type":"SBA","options":["Isolated osmotic diarrhoea without fat malabsorption","Primary inflammatory colitis with protein loss","Pancreatic exocrine insufficiency with incidental positive stool antigen","Mucosal malabsorption with relatively preserved exocrine pancreatic function"],"answer":"D","whyOptions":["Faecal fat is increased.","No convincing inflammatory stool pattern.","Elastase does not support significant pancreatic insufficiency.","Giardia plus increased stool fat and normal elastase supports intestinal malabsorption."],"explain":"Giardia plus increased stool fat and normal elastase supports intestinal malabsorption."},{"number":7,"q":"Which attachment structure is present on Giardia trophozoites?","type":"VSAQ","options":[],"answer":"Ventral adhesive disc","accepted":["ventral adhesive disk","adhesive disc","adhesive disk","sucking disc","ventral disc"],"explain":"The ventral disc permits adherence to small bowel epithelium."},{"number":8,"q":"Which drug class includes metronidazole?","type":"VSAQ","options":[],"answer":"Nitroimidazole","accepted":["nitroimidazoles"],"explain":"Reduction of the nitro group generates reactive products that damage DNA in susceptible organisms."}]},{"id":94007,"title":"A change in bowel habit after medication","core":["Constipation"],"module":"GIT","scenario":"A 71-year-old woman develops hard stools, straining and a feeling of incomplete evacuation after starting amitriptyline and codeine for chronic pain. She drinks little because of limited access to a toilet. She has no bleeding or weight loss. Abdominal examination is soft with mild lower abdominal fullness. Rectal examination finds hard stool.","labContext":"Hb (g/dL): 12.7  (Reference: 12–16)\nCorrected Ca (mmol/L): 2.35  (Reference: 2.20–2.60)\nTSH (mIU/L): 2.1  (Reference: 0.4–4.0)\nCreatinine (µmol/L): 78  (Reference: 45–90)","difficulty":"Challenge","difficultyRating":3,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 159–171, 227–233; Guide p. 350","questions":[{"number":1,"q":"Which combined medication effect contributes most directly to constipation?","type":"SBA","options":["Reduced gastric acid with increased colonic water secretion","Increased bile acid delivery with increased colonic contraction","Increased cholinergic secretion and opioid-mediated acceleration of transit","Reduced cholinergic motility and opioid-mediated inhibition of propulsive peristalsis"],"answer":"D","whyOptions":["Does not explain stool hardening.","Would tend towards diarrhoea.","Both are opposite to the expected effects.","Antimuscarinic and opioid effects slow intestinal transit."],"explain":"Antimuscarinic and opioid effects slow intestinal transit."},{"number":2,"q":"Why does slowed transit produce hard stools?","type":"SBA","options":["Prolonged contact allows greater net colonic water absorption","Accelerated rectal emptying reduces stool hydration","Reduced sodium absorption reduces stool water content","Increased intestinal chloride secretion increases stool dry mass"],"answer":"A","whyOptions":["The colon continues absorbing water as stool remains longer.","The transit is delayed.","Reduced sodium uptake would reduce water absorption.","Chloride secretion draws water into lumen."],"explain":"The colon continues absorbing water as stool remains longer."},{"number":3,"q":"Which laxative mechanism is associated with polyethylene glycol?","type":"SBA","options":["Direct activation of intestinal muscarinic receptors","Retention of luminal water by an osmotic agent","Inhibition of bacterial fermentation in the colon","Direct blockade of peripheral opioid receptors"],"answer":"B","whyOptions":["Not PEG's mechanism.","PEG draws or retains water in the lumen and softens stool.","Not its main action.","Describes peripherally acting opioid antagonists."],"explain":"PEG draws or retains water in the lumen and softens stool."},{"number":4,"q":"She develops intermittent leakage of small amounts of liquid stool. Which explanation best fits the rectal finding?","type":"SBA","options":["Pancreatic fat malabsorption","Inflammatory colitis with bloody exudate","Primary secretory diarrhoea due to enterotoxin","Overflow around impacted faeces"],"answer":"D","whyOptions":["Does not explain impaction.","No evidence of inflammatory symptoms.","Does not explain the hard retained stool.","Liquid stool may pass around a hard impaction."],"explain":"Liquid stool may pass around a hard impaction."},{"number":5,"q":"Which initial supervised approach addresses her likely causes safely?","type":"SBA","options":["Arrange routine surgical removal of colon before conservative measures","Review constipating medicines, assess impaction and tailor fluids, toileting and laxatives","Prescribe high-dose bulking fibre before assessing impaction","Add a constipating antidiarrhoeal for leakage"],"answer":"B","whyOptions":["Not appropriate initial treatment.","The intervention must address medication, physical and social contributors.","Can worsen symptoms if impaction or obstruction is present.","May aggravate impaction."],"explain":"The intervention must address medication, physical and social contributors."},{"number":6,"q":"Which interpretation should change the investigation plan?","context":"At a later visit she has unexplained weight loss and new test results:\nHb (g/dL): 9.5  (Reference: 12–16)\nMCV (fL): 70  (Reference: 80–100)\nFerritin (µg/L): 8  (Reference: 15–150)","isData":true,"type":"SBA","options":["Primary macrocytic anaemia explains the bowel symptoms","New iron deficiency with altered bowel habit requires evaluation for structural disease","Stable functional constipation with incidental normal iron stores","Medication-related constipation excludes a structural lesion"],"answer":"B","whyOptions":["MCV is low, not high.","Alarm features require prompt assessment, including colorectal pathology.","Ferritin and indices are abnormal.","Medication effects and structural disease can coexist."],"explain":"Alarm features require prompt assessment, including colorectal pathology."},{"number":7,"q":"Which parasympathetic nerves supply the distal colon and rectum?","type":"VSAQ","options":[],"answer":"Pelvic splanchnic nerves","accepted":["pelvic splanchnics","S2 S3 S4","S2–S4"],"explain":"Pelvic splanchnic nerves from S2–S4 support distal colonic and rectal motility."},{"number":8,"q":"Name the retained, compacted faecal mass that may cause overflow leakage.","type":"VSAQ","options":[],"answer":"Faecal impaction","accepted":["fecal impaction","impacted stool","faecaloma"],"explain":"Impaction can produce paradoxical overflow diarrhoea."}]},{"id":94008,"title":"Recurrent abdominal pain with fluctuating stool form","core":["Irritable Bowel Syndrome"],"module":"GIT","scenario":"A 25-year-old student describes nine months of recurrent lower abdominal pain linked to defaecation and changes in stool frequency and form. Symptoms fluctuate between hard and loose stools and worsen during examination stress. There is bloating but no nocturnal diarrhoea, bleeding, fever or weight loss. Examination is normal.","labContext":"Hb (g/dL): 13.0  (Reference: 12–16)\nCRP (mg/L): 2  (Reference: \u003c5)\nFaecal calprotectin (µg/g): 29  (Reference: \u003c50 (assay-dependent))\nAlbumin (g/L): 43  (Reference: 35–50)","difficulty":"Challenge","difficultyRating":3,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Distinction Expanded pp. 12–16 (Rome V discussion); Seven Core pp. 6–7; Guide p. 351","questions":[{"number":1,"q":"Which mechanism best explains significant symptoms despite the lack of inflammatory findings?","type":"SBA","options":["Irreversible pancreatic acinar destruction with maldigestion","Altered gut–brain signalling with visceral hypersensitivity and dysmotility","Persistent enteric bacterial invasion with mucosal ulceration","Progressive transmural immune-mediated intestinal destruction"],"answer":"B","whyOptions":["Would favour steatorrhoea and nutritional deficits.","IBS is a disorder of gut–brain interaction; genuine symptoms may occur without destructive pathology.","Would more often produce inflammatory features.","Characteristic of Crohn disease, not uncomplicated IBS."],"explain":"IBS is a disorder of gut–brain interaction; genuine symptoms may occur without destructive pathology."},{"number":2,"q":"Which feature most strongly supports this clinical pattern rather than isolated functional diarrhoea?","type":"SBA","options":["Steatorrhoea associated with weight loss","Constipation occurring only during opioid therapy","Frequent loose stools without abdominal pain","Recurrent abdominal pain associated with altered bowel habit"],"answer":"D","whyOptions":["Suggests malabsorption.","Suggests medication effect.","More consistent with functional diarrhoea.","Pain linked to defaecation or stool change is central to IBS."],"explain":"Pain linked to defaecation or stool change is central to IBS."},{"number":3,"q":"Why can stress worsen symptoms without implying they are imagined?","type":"SBA","options":["Stress eliminates intestinal sensory signalling","Central and enteric neural signalling modulates visceral sensitivity and motility","Stress inevitably produces bacterial infection","Stress directly creates chronic crypt abscesses"],"answer":"B","whyOptions":["Would not explain hypersensitivity.","The gut–brain axis provides a physiological link between stress and symptoms.","Not supported.","Not the characteristic mechanism."],"explain":"The gut–brain axis provides a physiological link between stress and symptoms."},{"number":4,"q":"Which effect explains why an antispasmodic can improve cramps without curing the disorder?","type":"SBA","options":["Suppression of antibody-mediated villous atrophy","Eradication of invasive intestinal organisms","Regeneration of ulcerated intestinal mucosa","Reduced intestinal smooth muscle contraction"],"answer":"D","whyOptions":["Not the drug's mechanism.","Antispasmodics are not antimicrobials.","No characteristic destructive lesion to heal.","Symptom relief does not necessarily normalise gut–brain signalling."],"explain":"Symptom relief does not necessarily normalise gut–brain signalling."},{"number":5,"q":"Which communication approach is most appropriate after reassuring assessment?","type":"SBA","options":["Order repeated invasive testing whenever symptoms recur unchanged","Explain that normal tests prove symptoms are not real","Validate symptoms, explain gut–brain mechanisms and agree on tailored management and safety netting","Prescribe indefinite restrictive diets without nutritional assessment"],"answer":"C","whyOptions":["Unnecessary testing can cause harm.","Invalid and clinically inaccurate.","A positive explanation and shared plan avoid dismissing the patient.","Overrestriction risks nutritional harm."],"explain":"A positive explanation and shared plan avoid dismissing the patient."},{"number":6,"q":"Which interpretation best compares the patients?","context":"A second patient with similar symptoms has these results:\nHb (g/dL): 9.8  (Reference: 12–16)\nCRP (mg/L): 47  (Reference: \u003c5)\nFaecal calprotectin (µg/g): 620  (Reference: \u003c50)","isData":true,"type":"SBA","options":["Both profiles establish IBS because pain relates to defaecation","Normal calprotectin establishes the exact cause of the first patient's symptoms","Raised calprotectin confirms ulcerative colitis without further testing","The second patient's inflammatory and anaemia findings warrant organic disease assessment"],"answer":"D","whyOptions":["Pain relationship does not override red flags.","It reduces likelihood of significant inflammation but is not definitive alone.","Calprotectin is nonspecific for intestinal inflammation.","IBS does not account for these alarm abnormalities."],"explain":"IBS does not account for these alarm abnormalities."},{"number":7,"q":"Which nervous system within the gut wall coordinates local motility and secretion?","type":"VSAQ","options":[],"answer":"Enteric nervous system","accepted":["ENS"],"explain":"Enteric circuits interact with central and autonomic pathways."},{"number":8,"q":"What term describes the increased perception of pain from normal intestinal distension?","type":"VSAQ","options":[],"answer":"Visceral hypersensitivity","accepted":["visceral hyperalgesia"],"explain":"Heightened visceral sensitivity is an important IBS mechanism."}]},{"id":94009,"title":"Burning discomfort and progressive swallowing difficulty","core":["Gastroesophageal Reflux Disease"],"module":"GIT","scenario":"A 50-year-old man with central obesity has recurrent retrosternal burning after meals and when lying down, with sour regurgitation. Antacids provide temporary relief. Over the past month he has developed progressive difficulty swallowing solid food. He denies exertional chest pain but has a family history of heart disease. Examination is unremarkable.","labContext":"Hb (g/dL): 12.2  (Reference: 13–17)\nMCV (fL): 79  (Reference: 80–100)\nBMI (kg/m²): 34  (Reference: 18.5–24.9 (adult))","difficulty":"Challenge","difficultyRating":3,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 68–81, 223–226; Guide p. 352; SV GIT upper tract","questions":[{"number":1,"q":"Which physiological disturbance most directly permits recurrent reflux?","type":"SBA","options":["Failure of lower oesophageal sphincter relaxation during swallowing","Excessive upper oesophageal sphincter contraction during inspiration","Inappropriate transient relaxation of the lower oesophageal sphincter","Increased pyloric sphincter relaxation causing retrograde colonic flow"],"answer":"C","whyOptions":["Typical of achalasia.","Does not explain gastric reflux.","Loss of the antireflux barrier allows gastric contents to enter oesophagus.","Not the antireflux mechanism."],"explain":"Loss of the antireflux barrier allows gastric contents to enter oesophagus."},{"number":2,"q":"Which protective property is relatively limited in oesophageal squamous mucosa compared with gastric mucosa?","type":"SBA","options":["Ability to form intercellular junctions","Resistance to sustained acid and pepsin exposure","Ability to receive mucosal blood flow","Ability to undergo epithelial renewal"],"answer":"B","whyOptions":["Both have junctional barriers.","The oesophagus lacks the stomach's specialised mucus-bicarbonate barrier.","Both tissues are vascularised.","Both epithelia can renew."],"explain":"The oesophagus lacks the stomach's specialised mucus-bicarbonate barrier."},{"number":3,"q":"Which action of a proton pump inhibitor explains sustained reduction in acid exposure?","type":"SBA","options":["Reversible neutralisation of luminal hydrogen ions","Competitive antagonism of parietal cell H₂ receptors","Irreversible inhibition of parietal cell H⁺/K⁺-ATPase","Mechanical tightening of the lower oesophageal sphincter"],"answer":"C","whyOptions":["Antacids act this way.","H₂ blockers act upstream.","Inhibits the final pathway of acid secretion.","PPIs do not correct sphincter function."],"explain":"Inhibits the final pathway of acid secretion."},{"number":4,"q":"Which histological change is associated with chronic reflux in Barrett oesophagus?","type":"SBA","options":["Replacement of columnar epithelium by keratinised squamous epithelium","Replacement of stratified squamous epithelium by intestinal-type columnar epithelium","Invasion of submucosa by malignant squamous cells","Loss of all epithelial cells with granulomatous inflammation"],"answer":"B","whyOptions":["Opposite direction.","Metaplasia is an adaptive change with dysplasia risk.","Describes established cancer, not metaplasia.","Not Barrett metaplasia."],"explain":"Metaplasia is an adaptive change with dysplasia risk."},{"number":5,"q":"Which feature requires escalation rather than continued empirical symptom treatment?","type":"SBA","options":["Postprandial sour regurgitation","Symptoms on lying supine","Temporary relief after antacids","Progressive solid-food dysphagia"],"answer":"D","whyOptions":["Typical reflux symptom without independent alarm significance.","Common reflux trigger.","Does not establish or exclude serious disease.","Alarm symptom requiring evaluation for stricture or malignancy."],"explain":"Alarm symptom requiring evaluation for stricture or malignancy."},{"number":6,"q":"Which interpretation best explains the dysphagia?","context":"Endoscopy and biopsies:\nDistal oesophagus: Smooth narrowing; inflamed mucosa  (Reference: Patent lumen)\nBiopsy: Fibrosis, no dysplasia or invasion in sampled tissue  (Reference: Normal squamous epithelium)","isData":true,"type":"SBA","options":["Uncomplicated reflux without structural changes","Diffuse oesophageal spasm due to uncoordinated contraction","Peptic stricture due to chronic inflammation and fibrosis","Achalasia due to loss of inhibitory myenteric neurons"],"answer":"C","whyOptions":["The narrowing establishes a structural complication.","Does not explain demonstrated fixed narrowing and fibrosis.","Mechanical narrowing causes progressive solid dysphagia; appropriate evaluation remains necessary.","Usually affects liquids and solids and shows impaired junction relaxation."],"explain":"Mechanical narrowing causes progressive solid dysphagia; appropriate evaluation remains necessary."},{"number":7,"q":"Name the epithelial adaptation that characterises Barrett oesophagus.","type":"VSAQ","options":[],"answer":"Intestinal metaplasia","accepted":["columnar metaplasia","metaplasia"],"explain":"Metaplastic epithelium can progress through dysplasia to adenocarcinoma."},{"number":8,"q":"Which anatomical landmark denotes the squamocolumnar junction?","type":"VSAQ","options":[],"answer":"Z line","accepted":["Z-line","Z junction","squamocolumnar junction"],"explain":"The Z-line marks the epithelial transition at the gastro-oesophageal junction in normal anatomy."}]},{"id":94010,"title":"Nocturnal epigastric discomfort","core":["Peptic Ulcer Disease"],"module":"GIT","scenario":"A 42-year-old woman has intermittent burning epigastric pain, frequently waking her at night. Food temporarily relieves it. She uses ibuprofen for headaches. She has no dysphagia, vomiting or melaena and is haemodynamically stable. Endoscopy identifies a duodenal ulcer; gastric biopsy shows antral inflammation with curved organisms.","labContext":"Hb (g/dL): 12.3  (Reference: 12–16)\nUrea (mmol/L): 5.0  (Reference: 2.5–7.8)\nLipase (U/L): 34  (Reference: 13–60)","difficulty":"Challenge","difficultyRating":3,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 82–92, 102–106; Guide p. 353","questions":[{"number":1,"q":"Which mechanism links antral infection to duodenal acid injury?","type":"SBA","options":["Increased duodenal bicarbonate secretion increases acid exposure","Reduced histamine release directly stimulates parietal cells","Reduced somatostatin inhibition increases gastrin-mediated acid secretion","Increased somatostatin promotes gastrin release"],"answer":"C","whyOptions":["Bicarbonate neutralises acid.","Histamine stimulates acid secretion.","Antral-predominant H. pylori may raise gastrin and acid output.","Somatostatin inhibits gastrin."],"explain":"Antral-predominant H. pylori may raise gastrin and acid output."},{"number":2,"q":"How does ibuprofen increase ulcer risk independently of infection?","type":"SBA","options":["Increased prostaglandin secretion inhibits epithelial repair","H₂-receptor activation reduces mucosal perfusion","Cyclooxygenase inhibition reduces mucosal prostaglandins","Direct stimulation of duodenal gastrin secretion"],"answer":"C","whyOptions":["Prostaglandins generally protect mucosa.","Not the principal NSAID mechanism.","Reduced mucus, bicarbonate and mucosal perfusion impair defence.","Not the principal effect."],"explain":"Reduced mucus, bicarbonate and mucosal perfusion impair defence."},{"number":3,"q":"Which bacterial enzyme helps the organism tolerate gastric acidity?","type":"SBA","options":["Coagulase forms a fibrin barrier","Catalase generates urea from ammonia","Urease generates ammonia from urea","Lipase hydrolyses gastric mucus into bicarbonate"],"answer":"C","whyOptions":["Associated with S. aureus.","Catalase breaks down hydrogen peroxide.","Ammonia buffers the local acidic environment.","Not the acid adaptation mechanism."],"explain":"Ammonia buffers the local acidic environment."},{"number":4,"q":"Which test is appropriate to assess eradication after treatment and appropriate medication washout?","type":"SBA","options":["Serum H. pylori IgG titre","Serum gastrin alone","Urea breath test","Faecal occult blood test"],"answer":"C","whyOptions":["Antibodies may remain positive after eradication.","Not specific for persistent infection.","Detects active urease-producing infection; stool antigen is another option.","Detects bleeding rather than H. pylori."],"explain":"Detects active urease-producing infection; stool antigen is another option."},{"number":5,"q":"Which approach best addresses her two major risk factors?","type":"SBA","options":["Antibiotic monotherapy while continuing daily NSAIDs","Prescribed eradication treatment and review of NSAID need","PPI alone indefinitely without eradication treatment","Antacid alone with repeat testing only if haemorrhage occurs"],"answer":"B","whyOptions":["Inadequate eradication strategy and continuing risk.","Treat active infection and remove mucosal injury where possible.","Acid suppression does not eradicate infection.","Does not address causes or follow-up."],"explain":"Treat active infection and remove mucosal injury where possible."},{"number":6,"q":"Which interpretation should determine urgency?","context":"She later develops sudden severe epigastric pain and a rigid abdomen.\nBP (mmHg): 86/54  (Reference: Approx. 90–120/60–80)\nHR (/min): 126  (Reference: 60–100)\nImaging: Free subdiaphragmatic gas  (Reference: Absent)","isData":true,"type":"SBA","options":["Isolated reflux-related oesophageal spasm","Perforated viscus with peritonitis requiring urgent surgical escalation","Gastric outlet obstruction without perforation","Uncomplicated ulcer pain with incidental free gas"],"answer":"B","whyOptions":["Does not explain peritonism.","A perforated ulcer can release gas and gastric contents into the peritoneum.","Typically vomiting and retention rather than free intraperitoneal gas.","Free gas and rigidity suggest perforation."],"explain":"A perforated ulcer can release gas and gastric contents into the peritoneum."},{"number":7,"q":"Which artery lies posterior to the first part of the duodenum?","type":"VSAQ","options":[],"answer":"Gastroduodenal artery","accepted":["GDA"],"explain":"Posterior duodenal ulcers may erode this artery and bleed."},{"number":8,"q":"Which peritoneal layer mediates sharply localised somatic pain after perforation?","type":"VSAQ","options":[],"answer":"Parietal peritoneum","accepted":[],"explain":"Somatic innervation of parietal peritoneum permits localised pain and guarding."}]},{"id":94011,"title":"Melaena and collapse after analgesic use","core":["Upper GI Bleed"],"module":"GIT","scenario":"A 65-year-old man taking aspirin and ibuprofen reports black sticky stools followed by coffee-ground vomiting. He feels dizzy when standing and has cool hands, delayed capillary refill and mild epigastric tenderness. No known liver disease. Initial haemoglobin was measured within an hour of the episode.","labContext":"BP (mmHg): 88/54  (Reference: Approx. 90–120/60–80)\nHR (/min): 124  (Reference: 60–100)\nHb (g/dL): 13.4  (Reference: 13–17)\nUrea (mmol/L): 18  (Reference: 2.5–7.8)\nCreatinine (µmol/L): 98  (Reference: 60–110)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 93–101; Combined GIT cluster 1; Guide p. 354","questions":[{"number":1,"q":"Why can the initial haemoglobin be deceptively preserved?","type":"SBA","options":["Whole blood is lost proportionately before redistribution of fluid","Digested haemoglobin is directly reabsorbed intact into plasma","Platelet aggregation increases haemoglobin production","Erythropoietin immediately restores circulating red cell mass"],"answer":"A","whyOptions":["Haemoglobin is a concentration; early blood loss removes cells and plasma together.","Digestion does not restore red cells.","Haemostasis does not produce haemoglobin.","Marrow response takes days."],"explain":"Haemoglobin is a concentration; early blood loss removes cells and plasma together."},{"number":2,"q":"Which mechanism contributes to a disproportionate urea elevation?","type":"SBA","options":["Direct renal secretion of intact haemoglobin produces urea","Increased renal creatinine filtration converts creatinine to urea","Reduced liver urea synthesis increases serum urea","Digestion and absorption of blood protein increases hepatic urea production"],"answer":"D","whyOptions":["Not the principal mechanism.","These are distinct metabolic products.","Reduced synthesis would tend to lower urea.","Hypoperfusion and urea reabsorption may also contribute."],"explain":"Hypoperfusion and urea reabsorption may also contribute."},{"number":3,"q":"How does aspirin impair primary haemostasis?","type":"SBA","options":["Vitamin K epoxide reductase inhibition reduces factor synthesis","Reversible thrombin inhibition reduces fibrin cross-linking","Irreversible platelet COX-1 inhibition reduces thromboxane A₂","ADP receptor blockade directly inhibits P2Y12"],"answer":"C","whyOptions":["Warfarin mechanism.","Not aspirin's mechanism.","Reduces platelet activation and aggregation for platelet lifespan.","Clopidogrel mechanism."],"explain":"Reduces platelet activation and aggregation for platelet lifespan."},{"number":4,"q":"Which initial action is safest?","type":"SBA","options":["Arrange outpatient gastroscopy after a course of oral PPI","Urgent ABC assessment, IV access, resuscitation and senior escalation","Await repeat haemoglobin before assessing circulation","Begin bowel preparation for colonoscopy before resuscitation"],"answer":"B","whyOptions":["Unsafe with shock.","Shock must be addressed before definitive endoscopy; arrange blood tests and crossmatch.","Clinical shock is sufficient to act.","Does not address immediate danger."],"explain":"Shock must be addressed before definitive endoscopy; arrange blood tests and crossmatch."},{"number":5,"q":"After initial stabilisation, which investigation can identify and treat a bleeding ulcer?","type":"SBA","options":["Abdominal ultrasound","Upper GI endoscopy","Barium swallow","Faecal occult blood test"],"answer":"B","whyOptions":["Limited utility for luminal bleeding.","Permits localisation, risk assessment and haemostasis.","Does not permit haemostasis.","Overt bleeding is already evident."],"explain":"Permits localisation, risk assessment and haemostasis."},{"number":6,"q":"Which interpretation is most appropriate?","context":"Repeat assessment after IV fluids:\nHb (g/dL): 9.1  (Reference: 13–17)\nEndoscopy: Ulcer with nonbleeding visible vessel  (Reference: No lesion)\nBP (mmHg): 106/68  (Reference: Approx. 90–120/60–80)","isData":true,"type":"SBA","options":["Low-risk clean-based ulcer with completed haemostasis","Normalised BP excludes future rebleeding","High-risk ulcer stigma despite absence of current spurting","Haemoglobin fall proves ongoing bleeding independent of fluid replacement"],"answer":"C","whyOptions":["A visible vessel is not a clean base.","Haemodynamic improvement does not remove lesion risk.","A visible vessel carries substantial rebleeding risk and warrants endoscopic assessment/treatment.","Haemodilution can contribute; use clinical trends."],"explain":"A visible vessel carries substantial rebleeding risk and warrants endoscopic assessment/treatment."},{"number":7,"q":"Which ligament marks the anatomical division between upper and lower GI bleeding?","type":"VSAQ","options":[],"answer":"Ligament of Treitz","accepted":["Treitz ligament","suspensory ligament of duodenum"],"explain":"Upper GI bleeding originates proximal to the duodenojejunal flexure."},{"number":8,"q":"Name the black, tarry stool produced by digested blood.","type":"VSAQ","options":[],"answer":"Melaena","accepted":["melena"],"explain":"Digestion of blood produces characteristic black stool."}]},{"id":94012,"title":"Bloody nocturnal diarrhoea in a young adult","core":["Ulcerative Colitis"],"module":"GIT","scenario":"A 23-year-old woman presents with six weeks of bloody stools, urgency and nocturnal defaecation. She has lower abdominal pain and fatigue, and recently developed tender red nodules on her shins. No recent travel. She is pale with left lower abdominal tenderness, no guarding.","labContext":"Hb (g/dL): 10.1  (Reference: 12–16)\nCRP (mg/L): 48  (Reference: \u003c5)\nAlbumin (g/L): 28  (Reference: 35–50)\nFaecal calprotectin (µg/g): 780  (Reference: \u003c50 (assay-dependent))","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 108–123; Combined GIT cluster 2; Guide p. 355","questions":[{"number":1,"q":"Which distribution of pathology most strongly supports the suspected inflammatory disorder?","type":"SBA","options":["Continuous inflammation beginning in rectum and limited mainly to mucosa","Patchy gastric antral inflammation without colonic involvement","Discontinuous transmural ileocolonic inflammation with fistulae","Isolated proximal small bowel villous atrophy"],"answer":"A","whyOptions":["Typical of UC, unlike segmental transmural Crohn disease.","Does not account for bloody diarrhoea.","Favours Crohn disease.","Favours coeliac disease or another malabsorptive process."],"explain":"Typical of UC, unlike segmental transmural Crohn disease."},{"number":2,"q":"Which cell population forms crypt abscesses in active disease?","type":"SBA","options":["Eosinophils accumulating within mesenteric granulomas","Neutrophils accumulating within crypt lumina","Plasma cells replacing submucosal vessels","Osteoclasts infiltrating the lamina propria"],"answer":"B","whyOptions":["Not the characteristic crypt abscess pattern.","Active UC produces cryptitis and crypt abscesses.","Plasma cells may occur but do not form typical acute crypt abscesses.","Not a mucosal inflammatory cell population."],"explain":"Active UC produces cryptitis and crypt abscesses."},{"number":3,"q":"Which property explains the diagnostic utility of faecal calprotectin?","type":"SBA","options":["It measures pancreatic protease output","It quantifies occult blood directly","It measures circulating autoantibody specificity","It reflects neutrophil-associated intestinal inflammation"],"answer":"D","whyOptions":["Faecal elastase measures pancreatic function.","A different stool test detects blood.","Not an autoantibody test.","Can distinguish inflammatory from functional patterns, but is not disease-specific."],"explain":"Can distinguish inflammatory from functional patterns, but is not disease-specific."},{"number":4,"q":"Which treatment principle distinguishes mesalazine from systemic glucocorticoids?","type":"SBA","options":["Both are suitable indefinite steroid maintenance agents","Mesalazine is a systemic antibacterial agent","Steroids are preferred lifelong maintenance because of rapid effect","Mesalazine can maintain remission; systemic steroids are mainly used for induction"],"answer":"D","whyOptions":["Mesalazine is not a steroid.","It is an anti-inflammatory 5-ASA agent.","Long-term adverse effects preclude routine maintenance.","Long-term systemic steroids have important adverse effects."],"explain":"Long-term systemic steroids have important adverse effects."},{"number":5,"q":"Which action is appropriate before attributing all bloody diarrhoea to autoimmune disease?","type":"SBA","options":["Investigate enteric infection and assess severity before supervised immunosuppression","Delay all assessment until symptoms persist for six months","Begin immunosuppression before obtaining an infection history","Begin antimotility therapy despite severe inflammation"],"answer":"A","whyOptions":["Infectious colitis can mimic or coexist with UC.","Bloody diarrhoea warrants timely evaluation.","Can worsen untreated infection.","May worsen colonic dilatation risk."],"explain":"Infectious colitis can mimic or coexist with UC."},{"number":6,"q":"Which complication requires immediate escalation?","context":"She becomes febrile and tachycardic with increasing abdominal distension.\nTemperature (°C): 39.1  (Reference: 36.5–37.5)\nHR (/min): 132  (Reference: 60–100)\nTransverse colon diameter (cm): 7.1  (Reference: \u003c6 (toxic megacolon criterion))","isData":true,"type":"SBA","options":["Mild proctitis without systemic involvement","Toxic megacolon with systemic toxicity","Uncomplicated IBS with excess intraluminal gas","Chronic constipation with stable faecal loading"],"answer":"B","whyOptions":["Does not fit the severity.","Nonobstructive colonic dilatation with toxicity risks perforation.","Systemic toxicity and marked dilatation are alarm features.","Does not explain severe inflammatory deterioration."],"explain":"Nonobstructive colonic dilatation with toxicity risks perforation."},{"number":7,"q":"Name the painful red subcutaneous nodules on her shins.","type":"VSAQ","options":[],"answer":"Erythema nodosum","accepted":[],"explain":"An extraintestinal inflammatory manifestation of IBD."},{"number":8,"q":"Which chronic complication justifies colorectal surveillance in longstanding extensive colitis?","type":"VSAQ","options":[],"answer":"Colorectal cancer","accepted":["colorectal carcinoma","colon cancer","colonic dysplasia","dysplasia"],"explain":"Chronic inflammation increases dysplasia and carcinoma risk."}]},{"id":94013,"title":"Unexplained microcytic anaemia","core":["Colorectal Cancer"],"module":"GIT","scenario":"A 68-year-old man reports progressive fatigue, reduced appetite and unintended weight loss. He has no visible rectal bleeding or abdominal distension. His brother had a bowel tumour at 52. Examination shows pallor and mild right iliac fossa fullness. He has never undergone colorectal screening.","labContext":"Hb (g/dL): 8.9  (Reference: 13–17)\nMCV (fL): 68  (Reference: 80–100)\nFerritin (µg/L): 7  (Reference: 30–300 (illustrative male))\nTransferrin saturation (%): 6  (Reference: 20–45)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 139–157; Guide p. 356; recalled 2026 cases p. 3","questions":[{"number":1,"q":"Why may a right-sided colorectal lesion present late with anaemia rather than obstruction?","type":"SBA","options":["Complete absence of visceral sensory innervation prevents anaemia","Narrow lumen and solid contents prevent bleeding","Wider lumen and liquid contents permit occult bleeding without early narrowing symptoms","Lack of vascular supply prevents tumour necrosis"],"answer":"C","whyOptions":["Anaemia results from blood loss, not sensation.","These features are more typical of left colon and do not prevent bleeding.","Right-sided tumours commonly cause chronic occult loss.","Tumours can bleed from fragile vasculature."],"explain":"Right-sided tumours commonly cause chronic occult loss."},{"number":2,"q":"Which mechanism explains the low MCV and ferritin?","type":"SBA","options":["Chronic blood loss depletes iron stores and restricts haem synthesis","Folate deficiency impairs DNA synthesis and reduces MCV","Inflammatory iron sequestration alone increases iron stores","Acute haemolysis increases iron excretion and causes macrocytosis"],"answer":"A","whyOptions":["Iron-restricted erythropoiesis produces microcytosis.","Folate deficiency typically causes macrocytosis.","Ferritin can be high in isolated inflammation; this very low result supports absolute deficiency.","Does not fit low ferritin and chronic occult bleeding."],"explain":"Iron-restricted erythropoiesis produces microcytosis."},{"number":3,"q":"Which early genetic event characterises the conventional adenoma–carcinoma sequence?","type":"SBA","options":["Loss of APC tumour suppressor function","Restoration of p53-mediated apoptosis","Increased mismatch repair activity","Activation of RB tumour suppressor function"],"answer":"A","whyOptions":["Dysregulated Wnt signalling contributes to adenoma formation.","Would oppose malignant progression.","Mismatch repair deficiency is an alternative pathway, not increased activity.","RB activation restrains proliferation."],"explain":"Dysregulated Wnt signalling contributes to adenoma formation."},{"number":4,"q":"Which investigation best confirms the suspected structural lesion?","type":"SBA","options":["Serum CEA alone","Stool occult blood alone","Colonoscopy with biopsy","Abdominal plain radiograph alone"],"answer":"C","whyOptions":["Not a diagnostic screening or confirmation test.","Does not establish tumour histology.","Allows visualisation and histological diagnosis.","May identify obstruction but not confirm carcinoma."],"explain":"Allows visualisation and histological diagnosis."},{"number":5,"q":"Which counselling approach is most appropriate?","type":"SBA","options":["Inform the family of confirmed cancer before discussing with the patient","Prescribe iron and discharge once symptoms improve","Explain concern about significant occult blood loss and arrange timely investigation","Reassure because no visible bleeding is present"],"answer":"C","whyOptions":["Diagnosis is unconfirmed and confidentiality matters.","May miss the cause.","Avoid attributing unexplained iron deficiency in an older man to diet alone.","Occult bleeding is common."],"explain":"Avoid attributing unexplained iron deficiency in an older man to diet alone."},{"number":6,"q":"Which interpretation best integrates histology and metastatic risk?","context":"Biopsy shows malignant gland-forming cells invading through the muscularis mucosae into submucosa; CT shows liver lesions suspicious for metastases.\nBiopsy: Invasive gland-forming lesion  (Reference: Normal crypts without invasion)\nCEA (µg/L): 22  (Reference: \u003c5 (assay/smoking dependent))","isData":true,"type":"SBA","options":["Noninvasive dysplasia with no metastatic potential","Squamous carcinoma with spread primarily via bile ducts","Invasive adenocarcinoma with potential portal venous spread to liver","Benign adenoma with liver lesions established as unrelated"],"answer":"C","whyOptions":["Invasion is demonstrated.","Histology and route are incorrect.","Gland formation and invasion establish adenocarcinoma; colonic venous drainage reaches liver via portal system.","Submucosal invasion establishes malignancy."],"explain":"Gland formation and invasion establish adenocarcinoma; colonic venous drainage reaches liver via portal system."},{"number":7,"q":"What is the most common histological type of colorectal carcinoma?","type":"VSAQ","options":[],"answer":"Adenocarcinoma","accepted":[],"explain":"Most colorectal malignancies arise from glandular epithelium."},{"number":8,"q":"Name a conventional benign precursor lesion in the adenoma–carcinoma sequence.","type":"VSAQ","options":[],"answer":"Adenomatous polyp","accepted":["adenoma","tubular adenoma","villous adenoma","tubulovillous adenoma"],"explain":"Adenomatous dysplasia can accumulate mutations and progress to carcinoma."}]},{"id":94014,"title":"Intermittent postprandial right upper quadrant pain","core":["Gallstones"],"module":"GIT","scenario":"A 39-year-old woman has four episodes of steady right upper abdominal pain following fatty meals. Each lasts about 90 minutes and resolves fully. She recently lost weight rapidly and takes an oestrogen-containing contraceptive. Examination between episodes is unremarkable.","labContext":"Temperature (°C): 36.7  (Reference: 36.5–37.5)\nWCC (×10⁹/L): 7.1  (Reference: 4–11)\nBilirubin (µmol/L): 12  (Reference: 3–21)\nALP (U/L): 88  (Reference: 40–120)","difficulty":"Challenge","difficultyRating":3,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 172–185; Guide p. 357; Combined GIT cluster 12","questions":[{"number":1,"q":"Which feature best distinguishes transient obstruction from established gallbladder inflammation?","type":"SBA","options":["Complete resolution between episodes without sustained inflammatory signs","Association with fatty meals","Nausea during pain","Radiation to right scapula"],"answer":"A","whyOptions":["Transient cystic duct obstruction causes biliary colic.","Gallbladder contraction may provoke both.","Nonspecific.","Can occur in both conditions."],"explain":"Transient cystic duct obstruction causes biliary colic."},{"number":2,"q":"Which alteration favours cholesterol stone formation?","type":"SBA","options":["Increased unconjugated bilirubin exclusively due to albumin binding","Reduced cholesterol with increased phospholipids","Cholesterol secretion exceeding bile salt and phospholipid solubilising capacity","Increased bile salts relative to cholesterol"],"answer":"C","whyOptions":["More relevant to pigment stones; albumin binding is in plasma.","Opposes supersaturation.","Supersaturation promotes nucleation and growth.","Generally favours solubilisation."],"explain":"Supersaturation promotes nucleation and growth."},{"number":3,"q":"Why does isolated cystic duct obstruction not usually cause jaundice?","type":"SBA","options":["Conjugated bilirubin cannot enter urine","Cystic duct obstruction prevents all bilirubin formation","Hepatic bile drains directly through the pancreatic duct","Hepatic bile can continue through common hepatic and common bile ducts"],"answer":"D","whyOptions":["It is water soluble and can enter urine in cholestasis.","Bilirubin production continues.","Incorrect anatomy.","The gallbladder is a side reservoir; liver drainage can remain patent."],"explain":"The gallbladder is a side reservoir; liver drainage can remain patent."},{"number":4,"q":"Which ultrasound feature favours mobile calculi over a fixed gallbladder polyp?","type":"SBA","options":["Anechoic gallbladder lumen with posterior enhancement","Mobile echogenic focus with posterior acoustic shadow","Diffuse wall oedema without intraluminal focus","Fixed nonshadowing mural focus"],"answer":"B","whyOptions":["Typical of fluid.","Stones often move and attenuate sound.","Nonspecific inflammatory or systemic finding.","More typical of a polyp."],"explain":"Stones often move and attenuate sound."},{"number":5,"q":"What is appropriate after recurrent uncomplicated symptomatic episodes?","type":"SBA","options":["Immediate emergency laparotomy while asymptomatic","Routine antibiotics after every resolved episode","Discuss symptom management, elective surgical assessment and warning signs","Reassure that diet permanently dissolves all stones"],"answer":"C","whyOptions":["Not appropriate for stable uncomplicated disease.","No evidence of infection.","Symptomatic stones warrant evaluation; antibiotics are not routine for uncomplicated colic.","Diet may reduce triggers but does not reliably remove stones."],"explain":"Symptomatic stones warrant evaluation; antibiotics are not routine for uncomplicated colic."},{"number":6,"q":"Which interpretation best accounts for these new findings?","context":"She returns with dark urine and pale stools but no fever.\nConjugated bilirubin (µmol/L): 73  (Reference: 0–5)\nALP (U/L): 390  (Reference: 40–120)\nALT (U/L): 120  (Reference: 7–40)\nCommon bile duct diameter (mm): 10  (Reference: Usually ≤6 (context-dependent))","isData":true,"type":"SBA","options":["Isolated cystic duct obstruction with patent hepatic outflow","Common bile duct obstruction producing cholestasis","Isolated hepatocellular injury without biliary obstruction","Primary unconjugated hyperbilirubinaemia due to haemolysis"],"answer":"B","whyOptions":["Does not explain cholestasis well.","Conjugated bilirubin and ductal dilatation support choledocholithiasis.","Disproportionate ALP and duct dilatation favour obstruction.","Wrong bilirubin fraction and no explanation for duct dilatation."],"explain":"Conjugated bilirubin and ductal dilatation support choledocholithiasis."},{"number":7,"q":"Which hormone stimulates gallbladder contraction after a fatty meal?","type":"VSAQ","options":[],"answer":"Cholecystokinin","accepted":["CCK"],"explain":"I cells release CCK in response to fats and amino acids."},{"number":8,"q":"Which pigment gives stool its brown colour and is reduced in obstructive jaundice?","type":"VSAQ","options":[],"answer":"Stercobilin","accepted":[],"explain":"Reduced intestinal bilirubin delivery decreases stercobilin formation."}]},{"id":94015,"title":"Persistent right-sided abdominal pain with fever","core":["Cholecystitis"],"module":"GIT","scenario":"A 55-year-old woman with diabetes has 20 hours of continuous right upper quadrant pain and vomiting. Previous similar episodes resolved spontaneously. She is febrile with localised guarding and stops inspiration abruptly when the examiner presses under the right costal margin. No jaundice.","labContext":"Temperature (°C): 38.7  (Reference: 36.5–37.5)\nHR (/min): 110  (Reference: 60–100)\nWCC (×10⁹/L): 17  (Reference: 4–11)\nCRP (mg/L): 128  (Reference: \u003c5)\nBilirubin (µmol/L): 17  (Reference: 3–21)","difficulty":"Challenge","difficultyRating":3,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 172–185; Guide p. 358; Combined GIT cluster 6","questions":[{"number":1,"q":"Which mechanism best explains progression from short episodes to persistent inflammation?","type":"SBA","options":["Intermittent cystic duct obstruction with complete decompression","Isolated common hepatic duct obstruction with reduced gallbladder filling","Sustained cystic duct obstruction causes distension, mural inflammation and impaired perfusion","Sustained pancreatic duct obstruction causes intrapancreatic enzyme activation"],"answer":"C","whyOptions":["Explains previous biliary colic, not persistent inflammation.","Does not explain the typical gallbladder findings.","Chemical inflammation can precede secondary infection.","Would favour pancreatitis."],"explain":"Chemical inflammation can precede secondary infection."},{"number":2,"q":"Why does inspiration provoke abrupt pain during subcostal palpation?","type":"SBA","options":["Inspiration stretches the rectal mesentery against the costal margin","Inspiration closes the cystic duct through vagal withdrawal","Diaphragmatic ascent compresses pancreatic tail against spleen","Diaphragmatic descent moves the inflamed gallbladder against the examining hand"],"answer":"D","whyOptions":["Incorrect anatomy.","Not the mechanism.","Direction and organ incorrect.","Anatomical basis of Murphy sign."],"explain":"Anatomical basis of Murphy sign."},{"number":3,"q":"Which vascular change can lead to gallbladder gangrene?","type":"SBA","options":["Increased lymphatic clearance decreases mural pressure","Impaired venous and lymphatic drainage followed by compromised mural perfusion","Reduced portal pressure alone causes cystic artery occlusion","Increased cystic artery flow with preserved outflow"],"answer":"B","whyOptions":["Would be protective.","Distension and oedema raise tissue pressure and impair perfusion.","Not the direct causal sequence.","Not the principal ischaemic mechanism."],"explain":"Distension and oedema raise tissue pressure and impair perfusion."},{"number":4,"q":"Which ultrasound combination is most supportive?","type":"SBA","options":["Mobile stones alone with thin wall","Impacted neck stone, wall thickening and pericholecystic fluid","Diffuse ascites and no focal gallbladder tenderness","Isolated pancreatic duct dilation with normal gallbladder"],"answer":"B","whyOptions":["Can be uncomplicated cholelithiasis.","Together with local signs and inflammation, supports acute cholecystitis.","Wall oedema can be nonspecific in systemic illness.","Suggests another source."],"explain":"Together with local signs and inflammation, supports acute cholecystitis."},{"number":5,"q":"Which initial management principle is most appropriate?","type":"SBA","options":["Urgent supervised assessment, analgesia, fluid support and surgical review","Discharge with antacids because bilirubin is normal","Treat only with a fatty meal to promote emptying","Wait for blood culture confirmation before all treatment"],"answer":"A","whyOptions":["Acute inflammation requires hospital assessment and appropriate antimicrobial/source management.","Normal bilirubin does not exclude acute cholecystitis.","May worsen pain and does not relieve an impacted stone.","Delays necessary care."],"explain":"Acute inflammation requires hospital assessment and appropriate antimicrobial/source management."},{"number":6,"q":"Which interpretation best fits the findings?","context":"Ultrasound and biochemical results:\nGallbladder wall (mm): 6  (Reference: ≤3 (fasting, contextual))\nCBD diameter (mm): 4  (Reference: Usually ≤6)\nALP (U/L): 109  (Reference: 40–120)\nLipase (U/L): 39  (Reference: 13–60)","isData":true,"type":"SBA","options":["Uncomplicated transient biliary colic","Ascending cholangitis from major common duct obstruction","Acute pancreatitis as the dominant process","Acute gallbladder inflammation with relatively preserved common duct drainage"],"answer":"D","whyOptions":["Persistent inflammatory signs and wall changes argue against it.","No substantial evidence of common duct obstruction.","Normal lipase and focal gallbladder pathology do not support it.","Cystic duct obstruction explains inflammatory findings without major cholestasis."],"explain":"Cystic duct obstruction explains inflammatory findings without major cholestasis."},{"number":7,"q":"Which nerve conveys referred pain from central diaphragmatic peritoneum to the shoulder?","type":"VSAQ","options":[],"answer":"Phrenic nerve","accepted":["right phrenic nerve"],"explain":"C3–C5 sensory convergence produces shoulder-tip referral."},{"number":8,"q":"What structural complication is suspected if she develops diffuse rigidity and sudden hypotension?","type":"VSAQ","options":[],"answer":"Gallbladder perforation","accepted":["perforation","gall bladder perforation","gallbladder rupture"],"explain":"Perforation with peritonitis requires immediate escalation."}]},{"id":94016,"title":"Severe epigastric pain radiating to the back","core":["Pancreatitis"],"module":"GIT","scenario":"A 44-year-old man develops severe constant epigastric pain and vomiting after a celebration. He has a history of episodic biliary-type pain and substantial alcohol intake. Sitting forward provides slight relief. Abdomen is tender with reduced bowel sounds but no rigidity.","labContext":"BP (mmHg): 98/64  (Reference: Approx. 90–120/60–80)\nHR (/min): 118  (Reference: 60–100)\nLipase (U/L): 1260  (Reference: 13–60)\nALT (U/L): 212  (Reference: 7–40)\nCorrected calcium (mmol/L): 2.07  (Reference: 2.20–2.60)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 203–221; Guide p. 359; Combined GIT cluster 4","questions":[{"number":1,"q":"Which molecular event contributes to pancreatic autodigestion?","type":"SBA","options":["Inhibition of pancreatic protease synthesis alone","Physiological trypsinogen activation in duodenum","Premature intrapancreatic trypsinogen activation","Intrapancreatic inactivation of all proteases"],"answer":"C","whyOptions":["Does not initiate autodigestion.","Normal digestion occurs outside the pancreas.","Trypsin activates other zymogens and amplifies injury.","Would oppose proteolytic injury."],"explain":"Trypsin activates other zymogens and amplifies injury."},{"number":2,"q":"Which anatomical location can explain simultaneous biliary and pancreatic injury?","type":"SBA","options":["Accessory pancreatic duct alone","Shared terminal duct region at hepatopancreatic ampulla","Common hepatic duct proximal to cystic junction","Cystic duct alone"],"answer":"B","whyOptions":["Does not explain impaired biliary drainage.","A migrating stone may obstruct both drainage pathways.","Does not directly obstruct pancreatic duct.","Does not obstruct pancreatic drainage directly."],"explain":"A migrating stone may obstruct both drainage pathways."},{"number":3,"q":"Which enzyme-mediated process contributes to reduced calcium?","type":"SBA","options":["Amylase-mediated starch breakdown binds serum calcium","Elastase-mediated urea formation increases calcium loss","Protease-mediated collagen cross-linking releases calcium","Lipase-mediated fat necrosis releases fatty acids that bind calcium"],"answer":"D","whyOptions":["Not the characteristic process.","Not the mechanism.","Not the mechanism.","Saponification contributes to true hypocalcaemia in severe disease."],"explain":"Saponification contributes to true hypocalcaemia in severe disease."},{"number":4,"q":"Why can the patient develop oedema while intravascular volume is depleted?","type":"SBA","options":["Reduced endothelial permeability causes extravascular accumulation","Increased oncotic pressure drives fluid out of capillaries","Increased lymphatic return causes fluid sequestration outside vessels","Inflammatory capillary leakage shifts fluid into interstitial and retroperitoneal spaces"],"answer":"D","whyOptions":["Would reduce leakage.","Oncotic pressure favours retention within vessels.","Would promote drainage.","Third spacing reduces effective circulating volume."],"explain":"Third spacing reduces effective circulating volume."},{"number":5,"q":"He develops hypoxaemia, oliguria and hypotension. Which priority is appropriate?","type":"SBA","options":["Start antibiotics solely because CRP rises","Urgent ABC reassessment, monitored fluids and escalation for organ support","Give unrestricted oral food despite persistent vomiting and shock","Delay escalation until lipase peaks"],"answer":"B","whyOptions":["Sterile inflammation may elevate CRP; infection must be assessed.","Systemic inflammation can cause shock, AKI and respiratory failure.","Initial stabilisation and safe nutritional planning take priority.","Lipase magnitude is not a severity measure."],"explain":"Systemic inflammation can cause shock, AKI and respiratory failure."},{"number":6,"q":"Which interpretation is most accurate?","context":"Serial laboratory trends:\nLipase (U/L), day 1 → 3: 1260 → 220  (Reference: 13–60)\nCreatinine (µmol/L), day 1 → 3: 94 → 240  (Reference: 60–110)\nCRP (mg/L), day 1 → 3: 24 → 210  (Reference: \u003c5)","isData":true,"type":"SBA","options":["Falling lipase establishes recovery despite worsening renal function","Declining lipase proves chronic pancreatic failure","Falling lipase does not exclude worsening systemic organ injury","Rising CRP proves bacterial infection requiring antibiotics"],"answer":"C","whyOptions":["Enzyme level is not a reliable severity marker.","Cannot establish chronic disease from this trend.","Organ function and clinical trends determine urgency.","CRP is nonspecific."],"explain":"Organ function and clinical trends determine urgency."},{"number":7,"q":"Name a mature encapsulated pancreatic fluid collection without epithelial lining or solid necrotic debris.","type":"VSAQ","options":[],"answer":"Pancreatic pseudocyst","accepted":["pseudocyst"],"explain":"Typically develops after several weeks; solid debris suggests walled-off necrosis instead."},{"number":8,"q":"Which histological type of necrosis produces chalky calcium deposits around the pancreas?","type":"VSAQ","options":[],"answer":"Fat necrosis","accepted":["enzymatic fat necrosis"],"explain":"Lipase releases fatty acids that form calcium soaps."}]},{"id":94017,"title":"Fatigue, bruising and confusion","core":["Liver Cirrhosis"],"module":"GIT","scenario":"A 56-year-old man with previous heavy alcohol use presents with fatigue, abdominal distension, bruising and reversal of sleep pattern. Examination shows spider naevi, palmar erythema, splenomegaly, mild jaundice and asterixis. His neck veins are not distended.","labContext":"Albumin (g/L): 24  (Reference: 35–50)\nINR: 1.9  (Reference: 0.8–1.2)\nPlatelets (×10⁹/L): 72  (Reference: 150–400)\nAST (U/L): 84  (Reference: 10–40)\nALT (U/L): 46  (Reference: 7–40)\nBilirubin (µmol/L): 58  (Reference: 3–21)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 186–202; Guide p. 360; recalled 2026 cases p. 2","questions":[{"number":1,"q":"Which histological pattern defines the underlying disease?","type":"SBA","options":["Isolated diffuse steatosis with preserved lobular architecture","Bridging fibrosis and regenerative nodules distorting hepatic architecture","Portal inflammation without architectural distortion","Acute centrilobular necrosis without fibrosis"],"answer":"B","whyOptions":["Fatty liver alone is not cirrhosis.","The combination defines cirrhosis.","May represent chronic hepatitis without cirrhosis.","Acute injury alone does not establish cirrhosis."],"explain":"The combination defines cirrhosis."},{"number":2,"q":"Which cell is chiefly responsible for excessive extracellular matrix deposition after chronic injury?","type":"SBA","options":["Sinusoidal endothelial cell","Kupffer cell","Activated hepatic stellate cell","Bile duct epithelial cell"],"answer":"C","whyOptions":["Contributes to vascular dysfunction; not principal collagen producer.","Resident macrophages contribute inflammatory signals but are not the main fibrogenic cell.","Transforms into a collagen-producing myofibroblast-like cell.","Not principal fibrogenic cell in the space of Disse."],"explain":"Transforms into a collagen-producing myofibroblast-like cell."},{"number":3,"q":"Which mechanism explains splenomegaly and thrombocytopenia together?","type":"SBA","options":["Reduced vitamin K absorption with isolated megakaryocyte destruction","Increased hepatic platelet production with splenic atrophy","Portal venous congestion with increased splenic platelet sequestration","Isolated factor VIII deficiency with platelet consumption"],"answer":"C","whyOptions":["Vitamin K primarily affects clotting factors.","Opposite findings.","Hypersplenism and reduced hepatic thrombopoietin can contribute.","Not characteristic of cirrhosis."],"explain":"Hypersplenism and reduced hepatic thrombopoietin can contribute."},{"number":4,"q":"How does lactulose reduce ammonia absorption?","type":"SBA","options":["Direct inhibition of hepatic urea-cycle enzymes","Alkalinisation converts ammonium to freely diffusible ammonia","Increased intestinal glutamine breakdown generates less ammonia","Colonic fermentation lowers pH and favours less absorbable ammonium"],"answer":"D","whyOptions":["Would impair ammonia clearance.","Would favour absorption.","Not its principal mechanism.","Catharsis also reduces nitrogenous substrate retention."],"explain":"Catharsis also reduces nitrogenous substrate retention."},{"number":5,"q":"What is the safest initial approach to new confusion in this patient?","type":"SBA","options":["Give sedatives routinely to restore sleep cycle","Increase diuretics until cognition improves","Assess ABCs and glucose, investigate infection, bleeding and other precipitants urgently","Attribute all confusion to alcohol withdrawal without assessment"],"answer":"C","whyOptions":["May worsen mental state and airway risk.","May precipitate volume/electrolyte deterioration.","Encephalopathy is a clinical syndrome; other causes and triggers must be assessed.","Unsafe anchoring."],"explain":"Encephalopathy is a clinical syndrome; other causes and triggers must be assessed."},{"number":6,"q":"Which interpretation best addresses diagnostic uncertainty?","context":"Serial values after diarrhoea and diuretic use:\nCreatinine (µmol/L): 90 → 178  (Reference: 60–110)\nSodium (mmol/L): 127  (Reference: 135–145)\nBP (mmHg): 86/56  (Reference: Approx. 90–120/60–80)","isData":true,"type":"SBA","options":["Creatinine rise establishes hepatorenal syndrome without further assessment","Hyponatraemia indicates excess effective circulating volume and need for more diuretic","Normal initial creatinine excludes renal injury","AKI in decompensated cirrhosis requires evaluation of hypovolaemia, infection and other causes before labelling hepatorenal syndrome"],"answer":"D","whyOptions":["Not specific.","Total water and effective arterial volume are distinct.","The subsequent rise is clinically important.","HRS is a diagnosis after appropriate evaluation; hypotension and losses suggest alternatives."],"explain":"HRS is a diagnosis after appropriate evaluation; hypotension and losses suggest alternatives."},{"number":7,"q":"Which hepatic protein contributes most directly to plasma oncotic pressure?","type":"VSAQ","options":[],"answer":"Albumin","accepted":[],"explain":"Reduced synthesis contributes to oedema and ascites."},{"number":8,"q":"Which named sign describes flapping lapses of sustained posture?","type":"VSAQ","options":[],"answer":"Asterixis","accepted":["flapping tremor"],"explain":"Negative myoclonus is associated with metabolic encephalopathy, including hepatic encephalopathy."}]},{"id":94018,"title":"New abdominal distension with systemic deterioration","core":["Ascites"],"module":"GIT","scenario":"A 59-year-old woman with known chronic liver disease reports progressive abdominal distension and early satiety. There is shifting dullness, bilateral ankle oedema and no elevated jugular venous pressure. She has developed diffuse abdominal discomfort and mild confusion. Her family reports recent reduced urine output.","labContext":"BP (mmHg): 92/60  (Reference: Approx. 90–120/60–80)\nTemperature (°C): 38.2  (Reference: 36.5–37.5)\nSerum albumin (g/L): 25  (Reference: 35–50)\nCreatinine (µmol/L): 156  (Reference: 45–90)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 186–202; Guide p. 361; Combined GIT cluster 15","questions":[{"number":1,"q":"Which combination contributes to accumulation of peritoneal fluid in chronic liver disease?","type":"SBA","options":["Increased plasma oncotic pressure and reduced lymph production","Isolated renal water loss with increased plasma protein concentration","Increased portal hydrostatic pressure and reduced plasma oncotic pressure","Reduced portal pressure and increased plasma oncotic pressure"],"answer":"C","whyOptions":["Does not favour filtration into peritoneum.","Would not explain this fluid accumulation.","Splanchnic vasodilatation and renal sodium retention further contribute.","Both oppose fluid accumulation."],"explain":"Splanchnic vasodilatation and renal sodium retention further contribute."},{"number":2,"q":"Why is RAAS activated despite increased total extracellular fluid?","type":"SBA","options":["Increased plasma oncotic pressure decreases renal perfusion","Increased atrial stretch directly stimulates renin","Splanchnic vasoconstriction increases effective perfusion","Splanchnic vasodilatation reduces effective arterial filling"],"answer":"D","whyOptions":["Oncotic pressure is reduced, not increased.","Atrial stretch promotes natriuretic peptide release.","Would tend to suppress renin.","Kidney senses reduced effective perfusion, causing salt and water retention."],"explain":"Kidney senses reduced effective perfusion, causing salt and water retention."},{"number":3,"q":"Which pharmacological target explains spironolactone's usefulness in uncomplicated cirrhotic ascites?","type":"SBA","options":["Direct Na-K-2Cl cotransporter inhibition in ascending limb","Carbonic anhydrase inhibition in proximal tubule","Vasopressin receptor activation in collecting duct","Mineralocorticoid receptor antagonism in distal nephron"],"answer":"D","whyOptions":["Loop diuretic mechanism.","Acetazolamide mechanism.","Would promote water retention.","Reduces aldosterone-mediated sodium retention; monitor potassium and renal function."],"explain":"Reduces aldosterone-mediated sodium retention; monitor potassium and renal function."},{"number":4,"q":"Which procedure is particularly important in new symptomatic ascites with fever?","type":"SBA","options":["Delay sampling until fever resolves","Routine therapeutic drainage without sampling","Diagnostic paracentesis with cell count and culture","Upper endoscopy as the sole initial investigation"],"answer":"C","whyOptions":["Could delay diagnosis of SBP.","Misses important diagnostic information.","Assesses for spontaneous bacterial peritonitis and fluid characteristics.","Does not assess peritoneal infection."],"explain":"Assesses for spontaneous bacterial peritonitis and fluid characteristics."},{"number":5,"q":"Which response to hypotension and possible infection is safest?","type":"SBA","options":["Increase diuretics immediately despite hypotension","Wait for culture confirmation before any resuscitation","Urgent sepsis assessment, resuscitation, sampling and prompt appropriate antibiotics","Give lactulose alone and observe"],"answer":"C","whyOptions":["May worsen perfusion.","Unsafe delay.","Potential SBP is dangerous; do not delay necessary therapy for culture results.","Does not treat likely infection."],"explain":"Potential SBP is dangerous; do not delay necessary therapy for culture results."},{"number":6,"q":"Which combination best interprets the results? SAAG cut-off is 11 g/L.","context":"Paracentesis results:\nSerum albumin (g/L): 25  (Reference: 35–50)\nAscitic albumin (g/L): 8  (Reference: Variable)\nAscitic neutrophils (cells/mm³): 560  (Reference: \u003c250)\nCulture: Pending  (Reference: No growth)","isData":true,"type":"SBA","options":["Low-gradient ascites with neutrophilic infection","High-gradient sterile ascites without infection","High-gradient ascites with neutrophilic infection consistent with SBP","Low-gradient uncomplicated ascites"],"answer":"C","whyOptions":["Gradient is 17, not low.","Neutrophils exceed threshold; culture can be negative.","SAAG 17 supports portal hypertension; neutrophils ≥250 support SBP absent a surgical source.","Neither component fits."],"explain":"SAAG 17 supports portal hypertension; neutrophils ≥250 support SBP absent a surgical source."},{"number":7,"q":"What is the abbreviation for serum albumin minus ascitic albumin?","type":"VSAQ","options":[],"answer":"SAAG","accepted":["serum ascites albumin gradient"],"explain":"A high SAAG supports portal hypertension as a mechanism."},{"number":8,"q":"What term describes infection of ascitic fluid without an identifiable surgically treatable intra-abdominal source?","type":"VSAQ","options":[],"answer":"Spontaneous bacterial peritonitis","accepted":["SBP"],"explain":"SBP requires urgent supervised treatment."}]},{"id":94019,"title":"Oliguria after several days of fluid loss","core":["Acute Kidney Injury"],"module":"Renal","scenario":"A 72-year-old man has four days of diarrhoea and poor intake. He takes enalapril, hydrochlorothiazide and recently began ibuprofen. He is dizzy, dry, tachycardic and has flat neck veins. Urine output has fallen. There is no palpable bladder or peripheral oedema.","labContext":"BP (mmHg): 88/56  (Reference: Approx. 90–120/60–80)\nHR (/min): 116  (Reference: 60–100)\nCreatinine (µmol/L), baseline → current: 90 → 192  (Reference: 60–110)\nPotassium (mmol/L): 5.9  (Reference: 3.5–5.1)\nUrine output (mL/kg/h), 8 h: 0.3  (Reference: ≥0.5 (adult AKI threshold))","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 18–31, 116–136, 203–221; Guide p. 339; 2026 GEMP 2 Cases pp. 4–5","questions":[{"number":1,"q":"Which combined arteriolar effect of the medicines worsens filtration during volume depletion?","type":"SBA","options":["Afferent and efferent dilatation","Afferent dilatation and efferent constriction","Afferent constriction and efferent dilatation","Afferent and efferent constriction"],"answer":"C","whyOptions":["NSAIDs oppose protective afferent dilatation.","Usually supports glomerular pressure.","NSAIDs inhibit prostaglandin-dependent afferent dilatation; ACE inhibition reduces efferent constriction.","ACE inhibition opposes efferent constriction."],"explain":"NSAIDs inhibit prostaglandin-dependent afferent dilatation; ACE inhibition reduces efferent constriction."},{"number":2,"q":"Which tubular response is expected if structural injury has not yet occurred?","type":"SBA","options":["Increased bicarbonate excretion with sodium wasting","Reduced urea reabsorption despite increased water reabsorption","Increased sodium and water conservation with concentrated urine","Reduced sodium reabsorption with dilute urine"],"answer":"C","whyOptions":["Not expected during volume depletion.","Urea reabsorption often increases in hypoperfusion.","Reduced perfusion activates sympathetic, RAAS and ADH responses.","More typical of impaired tubular function."],"explain":"Reduced perfusion activates sympathetic, RAAS and ADH responses."},{"number":3,"q":"Why may serum potassium rise despite diarrhoeal potassium loss?","type":"SBA","options":["Increased GFR reduces filtered potassium","Increased aldosterone activity suppresses potassium secretion","NSAIDs directly increase faecal potassium absorption","Reduced distal delivery and reduced aldosterone activity impair renal potassium secretion"],"answer":"D","whyOptions":["GFR is reduced, not increased.","Aldosterone normally promotes secretion.","Not the principal mechanism.","AKI and ACE inhibition reduce elimination."],"explain":"AKI and ACE inhibition reduce elimination."},{"number":4,"q":"What initial supervised action is most appropriate?","type":"SBA","options":["Continue ACE inhibitor and NSAID during aggressive diuresis","Restore perfusion with reassessed isotonic fluid, review medications and assess ECG/electrolytes","Start chronic dialysis solely because creatinine doubled","Restrict fluid because creatinine is elevated"],"answer":"B","whyOptions":["Risks worsening hypoperfusion.","Addresses the likely reversible insult and dangerous complications.","Not an indication alone.","Clinical signs indicate depletion."],"explain":"Addresses the likely reversible insult and dangerous complications."},{"number":5,"q":"The ward has no electronic fluid chart. Which practical action best improves monitoring?","type":"SBA","options":["Wait for electronic chart restoration before measuring output","Arrange measured urine collection, scheduled recording and escalation of deterioration","Rely on family estimation during visits","Use daily creatinine as the sole measure of fluid status"],"answer":"B","whyOptions":["Unsafe delay.","Provides actionable data despite system constraints.","Less reliable and inconsistent.","Does not capture rapid urine changes."],"explain":"Provides actionable data despite system constraints."},{"number":6,"q":"Which interpretation best integrates the findings?","context":"Urine obtained before fluid replacement, after thiazide ingestion:\nUrine osmolality (mOsm/kg): 640  (Reference: Variable)\nFeNa (%): 1.8  (Reference: \u003c1 supports pre-renal; >2 often tubular (limitations))\nMicroscopy: Hyaline casts only  (Reference: None or occasional hyaline casts)","isData":true,"type":"SBA","options":["Hyaline casts establish glomerulonephritis","Concentrated urine confirms postrenal obstruction","Diuretic-associated natriuresis may raise FeNa despite pre-renal physiology","FeNa definitively establishes tubular necrosis"],"answer":"C","whyOptions":["Hyaline casts are nonspecific; red cell casts suggest glomerular inflammation.","Not specific for obstruction.","Clinical depletion and preserved concentration support intact tubular function; FeNa has limitations.","Diuretic use makes interpretation less reliable."],"explain":"Clinical depletion and preserved concentration support intact tubular function; FeNa has limitations."},{"number":7,"q":"Which hormone preferentially constricts the efferent arteriole during moderate hypoperfusion?","type":"VSAQ","options":[],"answer":"Angiotensin II","accepted":["angiotensin 2","ANG II"],"explain":"Helps maintain glomerular pressure during volume depletion."},{"number":8,"q":"What is the commonly used term for the ACE inhibitor–diuretic–NSAID combination?","type":"VSAQ","options":[],"answer":"Triple whammy","accepted":["triple whammy effect"],"explain":"The combination compromises volume and glomerular autoregulation."}]},{"id":94020,"title":"Persistent oliguria despite restored blood pressure","core":["Acute Kidney Injury"],"module":"Renal","scenario":"A 61-year-old woman was admitted with septic hypotension and received supervised fluids and gentamicin. Three days later, infection and blood pressure have improved, but her creatinine continues to rise and urine output remains low. There is mild peripheral oedema and no bladder distension.","labContext":"BP (mmHg): 118/72  (Reference: Approx. 90–120/60–80)\nCreatinine (µmol/L), baseline → day 3: 79 → 312  (Reference: 45–90)\nPotassium (mmol/L): 6.1  (Reference: 3.5–5.1)\nUrine output (mL/kg/h): 0.25  (Reference: ≥0.5 (adult))","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 18–31, 203–221; Guide p. 339; Renal/Urology bank AKI","questions":[{"number":1,"q":"Which finding most strongly suggests intrinsic injury beyond simple hypoperfusion?","type":"SBA","options":["Persistent oliguria and creatinine rise after haemodynamic recovery","Initial hypotension","Previous systemic infection","Mild ankle oedema"],"answer":"A","whyOptions":["Raises concern for established structural injury after ischaemia and nephrotoxin exposure.","Supports hypoperfusion but not structural injury alone.","Can produce either pre-renal or intrinsic AKI.","Nonspecific in AKI."],"explain":"Raises concern for established structural injury after ischaemia and nephrotoxin exposure."},{"number":2,"q":"Which pathological process contributes directly to reduced effective filtration?","type":"SBA","options":["Tubular epithelial injury with intraluminal obstruction and filtrate backleak","Immune complex deposition with red cell cast formation","Isolated efferent arteriolar dilatation without tubular injury","Isolated podocyte injury with massive albumin loss"],"answer":"A","whyOptions":["Injured cells detach and obstruct tubules; microvascular changes also contribute.","Would favour nephritic inflammation.","A haemodynamic mechanism alone is less consistent with persistent dysfunction.","Nephrotic pattern, not the dominant mechanism here."],"explain":"Injured cells detach and obstruct tubules; microvascular changes also contribute."},{"number":3,"q":"How can gentamicin contribute to the renal injury?","type":"SBA","options":["Inhibition of renal prostaglandin synthesis","Blockade of angiotensin II formation","Immune complex deposition primarily in glomerular capillaries","Accumulation in proximal tubular cells with cellular toxicity"],"answer":"D","whyOptions":["NSAID effect.","ACE inhibitor effect.","Not characteristic of gentamicin toxicity.","Aminoglycosides cause direct tubular injury."],"explain":"Aminoglycosides cause direct tubular injury."},{"number":4,"q":"Which urine pattern is most consistent with widespread tubular dysfunction?","type":"SBA","options":["Red cell casts with dysmorphic erythrocytes","Reduced sodium conservation and impaired urine concentration","Heavy isolated albuminuria with preserved tubular function","Increased sodium conservation and highly concentrated urine"],"answer":"B","whyOptions":["Glomerular bleeding rather than typical tubular injury.","Damaged tubular epithelium cannot reabsorb solutes and concentrate urine normally.","Glomerular protein barrier defect.","Typical of intact response to hypoperfusion."],"explain":"Damaged tubular epithelium cannot reabsorb solutes and concentrate urine normally."},{"number":5,"q":"Potassium rises to 6.8 mmol/L with QRS widening. Which action directly stabilises cardiac electrical excitability?","type":"SBA","options":["Oral potassium binder alone","Loop diuretic alone","Urgent supervised IV calcium","IV insulin with glucose alone"],"answer":"C","whyOptions":["Too slow to address immediate electrical risk.","May not work in severe oliguria and does not directly stabilise myocardium.","Stabilises myocardial membrane; additional potassium-lowering measures are required.","Shifts potassium but does not directly stabilise cardiac membrane."],"explain":"Stabilises myocardial membrane; additional potassium-lowering measures are required."},{"number":6,"q":"Which interpretation fits the combined data?","context":"Urine and imaging findings:\nFeNa (%): 3.6  (Reference: \u003c1 pre-renal; >2 often tubular (limitations))\nUrine osmolality (mOsm/kg): 286  (Reference: Variable)\nMicroscopy: Muddy brown granular casts  (Reference: Absent)\nRenal ultrasound: No hydronephrosis  (Reference: No hydronephrosis)","isData":true,"type":"SBA","options":["Established bilateral mechanical obstruction","Predominant glomerular inflammation","Isolated pre-renal dysfunction with intact tubular function","Acute tubular injury with impaired reabsorptive function"],"answer":"D","whyOptions":["Imaging does not support it; early obstruction can occasionally lack dilation.","No active glomerular sediment is described.","Does not fit granular casts and concentrating impairment.","Granular casts, low concentrating ability and high FeNa are supportive."],"explain":"Granular casts, low concentrating ability and high FeNa are supportive."},{"number":7,"q":"Which temporary renal support is considered for refractory hyperkalaemia and pulmonary oedema?","type":"VSAQ","options":[],"answer":"Renal replacement therapy","accepted":["RRT","dialysis","haemodialysis","hemodialysis"],"explain":"Refractory life-threatening complications warrant urgent renal/critical care assessment."},{"number":8,"q":"Which hormone is given with glucose to shift potassium intracellularly?","type":"VSAQ","options":[],"answer":"Insulin","accepted":["regular insulin","soluble insulin"],"explain":"Stimulates Na⁺/K⁺-ATPase and shifts potassium into cells."}]},{"id":94021,"title":"Frequent small voids and suprapubic swelling","core":["Acute Kidney Injury"],"module":"Renal","scenario":"A 76-year-old man has progressive lower abdominal discomfort, a weak stream and frequent small-volume voids. He started amitriptyline one week ago. There is a smooth suprapubic mass dull to percussion and a smooth enlarged prostate. He has mild ankle oedema.","labContext":"Creatinine (µmol/L), baseline → current: 98 → 352  (Reference: 60–110)\nPotassium (mmol/L): 5.8  (Reference: 3.5–5.1)\nBicarbonate (mmol/L): 17  (Reference: 22–26)\nBP (mmHg): 156/90  (Reference: Approx. 90–120/60–80)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 24–31, 160–171; Guide p. 339; renal bank retention mechanism","questions":[{"number":1,"q":"Which finding most strongly supports retention despite continued voiding?","type":"SBA","options":["Ankle oedema with elevated creatinine","Nocturia alone","Palpable bladder with repeated small-volume voids","Raised blood pressure alone"],"answer":"C","whyOptions":["Indicates renal/fluid disturbance but not its location.","Nonspecific.","Overflow or incomplete emptying may occur despite frequent urine passage.","Does not localise obstruction."],"explain":"Overflow or incomplete emptying may occur despite frequent urine passage."},{"number":2,"q":"Which Starling force change reduces GFR most directly?","type":"SBA","options":["Reduced Bowman's space hydrostatic pressure","Increased glomerular capillary hydrostatic pressure","Increased hydrostatic pressure in Bowman's space","Reduced glomerular capillary oncotic pressure"],"answer":"C","whyOptions":["Would favour filtration.","Generally favours filtration.","Upstream urinary back pressure opposes glomerular filtration.","Would favour filtration."],"explain":"Upstream urinary back pressure opposes glomerular filtration."},{"number":3,"q":"Which pharmacological effect of amitriptyline may worsen retention?","type":"SBA","options":["Muscarinic antagonism reduces detrusor contraction","Muscarinic agonism reduces detrusor contraction","Beta-1 antagonism directly increases prostate volume","Alpha-1 antagonism increases bladder outlet tone"],"answer":"A","whyOptions":["Anticholinergic effect impairs emptying.","Muscarinic stimulation promotes contraction.","Not a characteristic mechanism.","Alpha-1 blockade generally reduces outlet tone."],"explain":"Anticholinergic effect impairs emptying."},{"number":4,"q":"Which imaging pattern best supports obstruction sufficient to impair global renal function?","type":"SBA","options":["Unilateral hydronephrosis with normal contralateral kidney","Bilateral hydronephrosis with large bladder residual","Isolated small renal cortical cyst","Bilateral cortical thinning with empty bladder"],"answer":"B","whyOptions":["May preserve overall filtration when other kidney functions.","Outlet obstruction may affect drainage from both kidneys.","Unlikely to explain global obstruction.","Suggests chronic parenchymal disease rather than direct evidence of retention."],"explain":"Outlet obstruction may affect drainage from both kidneys."},{"number":5,"q":"Which action directly addresses the reversible insult?","type":"SBA","options":["Wait for alpha-blocker response before assessing drainage","Give repeated fluid boluses until urine output rises","Diuretic trial before drainage","Prompt supervised bladder decompression and renal/electrolyte monitoring"],"answer":"D","whyOptions":["May delay necessary decompression.","May worsen overload with obstruction.","Does not relieve obstruction.","Relief of obstruction is urgent; escalate if catheterisation fails."],"explain":"Relief of obstruction is urgent; escalate if catheterisation fails."},{"number":6,"q":"Which interpretation requires ongoing supervision?","context":"After drainage of 1.4 L, urine output averages 350 mL/h for 6 hours.\nBP (mmHg): 96/60  (Reference: Approx. 90–120/60–80)\nNa (mmol/L): 147  (Reference: 135–145)\nK (mmol/L): 3.2  (Reference: 3.5–5.1)","isData":true,"type":"SBA","options":["Persistent obstruction requiring additional diuretics","Normal recovery with no requirement for monitoring","Post-obstructive diuresis with evolving volume and electrolyte depletion","SIADH causing dilutional hyponatraemia"],"answer":"C","whyOptions":["High urine output after drainage does not suggest this as primary explanation.","The haemodynamic and electrolyte changes indicate risk.","Large sustained output after obstruction can cause hypotension and electrolyte loss.","Sodium is increased, not reduced."],"explain":"Large sustained output after obstruction can cause hypotension and electrolyte loss."},{"number":7,"q":"Name dilatation of renal pelvis and calyces due to impaired drainage.","type":"VSAQ","options":[],"answer":"Hydronephrosis","accepted":[],"explain":"Back pressure may compromise renal filtration."},{"number":8,"q":"Which ultrasound-derived measurement quantifies urine remaining after voiding?","type":"VSAQ","options":[],"answer":"Post-void residual","accepted":["postvoid residual","PVR","post void residual volume","bladder residual volume"],"explain":"Helps assess incomplete bladder emptying."}]},{"id":94022,"title":"Dark urine following prolonged exercise","core":["Acute Kidney Injury"],"module":"Renal","scenario":"A 30-year-old man presents after an endurance event in hot weather. He has severe thigh pain, dehydration and dark brown urine with low output. He took ibuprofen during recovery. Examination shows tender swollen thigh muscles and dry mucosa.","labContext":"Creatinine (µmol/L), baseline → current: 86 → 276  (Reference: 60–110)\nPotassium (mmol/L): 6.2  (Reference: 3.5–5.1)\nBicarbonate (mmol/L): 15  (Reference: 22–26)\nCK (U/L): 28000  (Reference: 30–200 (lab dependent))","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 18–31, 203–221; Guide p. 339; Paper 2 practice cluster 8","questions":[{"number":1,"q":"Which process best explains the renal insult in addition to dehydration?","type":"SBA","options":["Haemoglobin release from immune-mediated erythrocyte lysis","Massive albumin loss due to podocyte effacement","Myoglobin-associated tubular toxicity and cast formation","Uric acid precipitation from tumour lysis"],"answer":"C","whyOptions":["No haemolytic history; CK and muscle pain support muscle breakdown.","Does not account for muscle injury and pigment.","Rhabdomyolysis releases myoglobin, which contributes to oxidative injury and obstruction.","No such history; muscle injury dominates."],"explain":"Rhabdomyolysis releases myoglobin, which contributes to oxidative injury and obstruction."},{"number":2,"q":"Which mechanism contributes to potassium elevation?","type":"SBA","options":["Reduced cellular potassium release and increased faecal loss","Increased aldosterone and increased distal flow","Potassium uptake into injured myocytes plus enhanced secretion","Release from injured myocytes plus impaired renal excretion"],"answer":"D","whyOptions":["Would oppose hyperkalaemia.","Would favour elimination.","Would lower serum potassium.","Rhabdomyolysis and AKI both raise potassium."],"explain":"Rhabdomyolysis and AKI both raise potassium."},{"number":3,"q":"Which pharmacological mechanism worsens perfusion during dehydration?","type":"SBA","options":["Activation of renal prostaglandin synthesis","ACE inhibition reduces angiotensin II generation","COX inhibition reduces afferent prostaglandin-mediated vasodilatation","Direct renal aldosterone receptor blockade"],"answer":"C","whyOptions":["NSAIDs inhibit synthesis.","Not the NSAID target.","Ibuprofen reduces compensatory renal blood flow.","Spironolactone mechanism."],"explain":"Ibuprofen reduces compensatory renal blood flow."},{"number":4,"q":"What finding requires immediate cardiac assessment?","type":"SBA","options":["CK elevation alone despite normal electrolytes","Marked hyperkalaemia with muscle weakness and AKI","Dark urine alone","Mild dehydration alone"],"answer":"B","whyOptions":["Important but not the most immediate electrical threat.","Arrhythmia risk mandates urgent ECG and supervised treatment.","Requires assessment but not as specific for cardiac danger.","Less direct cardiac risk than hyperkalaemia."],"explain":"Arrhythmia risk mandates urgent ECG and supervised treatment."},{"number":5,"q":"Which fluid strategy is safest in early pigment-associated AKI?","type":"SBA","options":["Unrestricted fluid irrespective of pulmonary findings","Routine fluid restriction before assessing depletion","Supervised isotonic fluid with repeated assessment of perfusion, output and overload","Diuretics as sole prevention of tubular injury"],"answer":"C","whyOptions":["Can cause overload if oliguric.","May worsen hypoperfusion.","Correct hypovolaemia while monitoring evolving renal function.","Do not substitute for correcting perfusion."],"explain":"Correct hypovolaemia while monitoring evolving renal function."},{"number":6,"q":"Which interpretation best explains positive haem testing with few RBCs?","context":"Urine testing:\nDipstick haem: 3+  (Reference: Negative)\nRBC per high-power field: 0–2  (Reference: 0–2)\nMicroscopy: Pigmented granular casts  (Reference: Absent)","isData":true,"type":"SBA","options":["Urate crystalluria generates a positive haem reaction","Filtered myoglobin produces a positive haem reaction","Isolated conjugated bilirubin produces haem signal","Glomerular haematuria with abundant dysmorphic RBCs"],"answer":"B","whyOptions":["Not a direct explanation.","Dipstick detects haem activity, not only intact erythrocytes.","Bilirubin has a separate dipstick pad.","Microscopy does not demonstrate this."],"explain":"Dipstick detects haem activity, not only intact erythrocytes."},{"number":7,"q":"Name the oxygen-binding muscle protein responsible for pigmenturia.","type":"VSAQ","options":[],"answer":"Myoglobin","accepted":[],"explain":"Filtered after skeletal muscle injury."},{"number":8,"q":"What clinical syndrome describes extensive skeletal muscle breakdown?","type":"VSAQ","options":[],"answer":"Rhabdomyolysis","accepted":[],"explain":"Muscle breakdown releases CK, myoglobin and intracellular electrolytes."}]},{"id":94023,"title":"Progressive fatigue, pruritus and ankle swelling","core":["Chronic Kidney Disease"],"module":"Renal","scenario":"A 63-year-old woman with longstanding hypertension and diabetes reports fatigue, itch, poor appetite and swelling. Records show progressively reduced renal function over 18 months. She is pale and has pitting oedema. Her kidneys are small and echogenic with cortical thinning on ultrasound.","labContext":"Hb (g/dL): 8.8  (Reference: 12–16)\nMCV (fL): 88  (Reference: 80–100)\nFerritin (µg/L): 165  (Reference: 15–150 (lab dependent))\nTSAT (%): 27  (Reference: 20–45)\nBicarbonate (mmol/L): 17  (Reference: 22–26)\nCreatinine (µmol/L): 248  (Reference: 45–90)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 57–81, 82–112; Guide p. 340; Paper 2 practice cluster 9","questions":[{"number":1,"q":"Which mechanism most directly explains the hypoproliferative normocytic anaemia?","type":"SBA","options":["Reduced renal erythropoietin production by peritubular interstitial cells","Increased peripheral haemolysis with intact marrow response","Reduced hepatic thrombopoietin production","Isolated iron depletion causing severe microcytosis"],"answer":"A","whyOptions":["Reduced EPO limits marrow erythroid proliferation; inflammation may contribute.","Typically increases reticulocytes.","Primarily affects platelets.","Iron indices and MCV do not favour isolated deficiency."],"explain":"Reduced EPO limits marrow erythroid proliferation; inflammation may contribute."},{"number":2,"q":"Which adaptation initially contributes to progressive nephron damage?","type":"SBA","options":["Hyperfiltration and increased intraglomerular pressure in remaining nephrons","Complete suppression of filtration in all surviving nephrons","Reduced single-nephron flow with no compensatory change","Increased tubular secretion restoring lost nephron number"],"answer":"A","whyOptions":["Compensation can accelerate glomerular injury and sclerosis.","Not the characteristic early adaptive response.","Does not explain hyperfiltration injury.","Secretion does not regenerate nephrons."],"explain":"Compensation can accelerate glomerular injury and sclerosis."},{"number":3,"q":"Why does an ACE inhibitor reduce albuminuria in an appropriately selected stable patient?","type":"SBA","options":["Afferent constriction via increased angiotensin II","Efferent constriction raises filtration pressure","Efferent arteriolar dilatation lowers intraglomerular pressure","Direct restoration of lost podocytes"],"answer":"C","whyOptions":["ACE inhibition reduces angiotensin II.","Would worsen glomerular pressure.","Reduces albumin filtration; monitor potassium and creatinine.","Not its pharmacological mechanism."],"explain":"Reduces albumin filtration; monitor potassium and creatinine."},{"number":4,"q":"Which renal change contributes to the low bicarbonate?","type":"SBA","options":["Increased pulmonary carbon dioxide retention as the primary renal effect","Isolated increase in renal bicarbonate reabsorption","Reduced total ammonium excretion and impaired new bicarbonate generation","Increased ammonium excretion with excessive bicarbonate generation"],"answer":"C","whyOptions":["Respiratory acidosis is a different mechanism.","Would not explain low bicarbonate.","Loss of nephron mass impairs net acid excretion.","Would counter acidosis."],"explain":"Loss of nephron mass impairs net acid excretion."},{"number":5,"q":"What should guide counselling about the possibility of dialysis?","type":"SBA","options":["Arrange immediate dialysis solely from a single eGFR value","Promise dialysis will never be needed","Explain trends, symptoms and complications; arrange renal follow-up and shared planning","Avoid discussing treatment options until an emergency"],"answer":"C","whyOptions":["Not appropriate without clinical assessment.","Cannot guarantee prognosis.","Dialysis decisions depend on clinical indications and patient circumstances, not one creatinine alone.","Limits informed planning."],"explain":"Dialysis decisions depend on clinical indications and patient circumstances, not one creatinine alone."},{"number":6,"q":"Which staging classification is correct?","context":"Serial stable outpatient results:\neGFR (mL/min/1.73 m²), 18 mo → now: 43 → 19  (Reference: ≥90 (G1))\nACR (mg/mmol): 92  (Reference: \u003c3 (A1))\nDuration: 18 months  (Reference: CKD requires ≥3 months)","isData":true,"type":"SBA","options":["CKD G5 A3","CKD G3b A2","CKD G4 A3","AKI stage 3 without chronic disease"],"answer":"C","whyOptions":["G5 is eGFR \u003c15.","G3b = 30–44; A2 = 3–30.","G4 = 15–29; A3 >30 mg/mmol.","Chronicity and structure establish CKD."],"explain":"G4 = 15–29; A3 >30 mg/mmol."},{"number":7,"q":"Which amino acid is metabolised in proximal tubules to generate ammonium?","type":"VSAQ","options":[],"answer":"Glutamine","accepted":["L-glutamine"],"explain":"Ammoniagenesis enables urinary acid excretion and new bicarbonate generation."},{"number":8,"q":"Name the nodular glomerular lesion typical of diabetic nephropathy.","type":"VSAQ","options":[],"answer":"Kimmelstiel Wilson nodules","accepted":["Kimmelstiel-Wilson nodule","Kimmelstiel-Wilson","nodular glomerulosclerosis"],"explain":"Mesangial matrix expansion can form characteristic nodules."}]},{"id":94024,"title":"Bone discomfort and biochemical deterioration","core":["Chronic Kidney Disease"],"module":"Renal","scenario":"A 52-year-old man with stage 4 chronic renal impairment has diffuse bone pain, weakness and itching. He has missed follow-up and takes phosphate-containing supplements bought without advice. His examination reveals pallor and mild oedema. There is no acute joint inflammation.","labContext":"eGFR (mL/min/1.73 m²): 18  (Reference: ≥90)\nCorrected Ca (mmol/L): 2.03  (Reference: 2.20–2.60)\nPhosphate (mmol/L): 2.10  (Reference: 0.80–1.45)\nPTH (pmol/L): 38  (Reference: 1.6–6.9)\nALP (U/L): 220  (Reference: 40–120)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 70–80, 101–112; Guide p. 340; Distinction Expanded pp. 32–37","questions":[{"number":1,"q":"Which primary renal changes drive this endocrine response?","type":"SBA","options":["Increased calcitriol with autonomous suppression of PTH","Phosphate retention and reduced calcitriol synthesis","Phosphate wasting and increased calcitriol synthesis","Increased renal calcium excretion due to low PTH"],"answer":"B","whyOptions":["Does not fit the findings.","Reduced filtration and activation contribute to secondary hyperparathyroidism.","Opposite pattern in advanced CKD.","PTH is elevated."],"explain":"Reduced filtration and activation contribute to secondary hyperparathyroidism."},{"number":2,"q":"Which enzyme activity is reduced with loss of functional renal tissue?","type":"SBA","options":["Skin UVB-dependent production of cholecalciferol","Hepatic 25-hydroxylation as the principal renal reaction","Intestinal calcium-binding protein hydrolysis","1α-hydroxylase-mediated formation of calcitriol"],"answer":"D","whyOptions":["Occurs in skin.","25-hydroxylation is primarily hepatic.","Not the renal activation step.","Renal CYP27B1 converts calcidiol to active vitamin D."],"explain":"Renal CYP27B1 converts calcidiol to active vitamin D."},{"number":3,"q":"How does persistently elevated PTH promote bone resorption?","type":"SBA","options":["Direct inhibition of osteoclast maturation by PTH","Osteoblast-lineage RANKL signalling increases osteoclast differentiation","Reduced RANKL promotes osteoclast survival","Increased osteoprotegerin activates osteoclast RANK"],"answer":"B","whyOptions":["Opposite effect.","PTH acts indirectly on osteoclasts through osteoblast-lineage cells.","Reduced signalling restrains osteoclasts.","OPG inhibits RANKL."],"explain":"PTH acts indirectly on osteoclasts through osteoblast-lineage cells."},{"number":4,"q":"Which treatment mechanism reduces phosphate burden in appropriate CKD care?","type":"SBA","options":["Increased dietary phosphate to suppress PTH","Loop diuretic blockade of intestinal phosphate transport","Intestinal phosphate binding reduces dietary absorption","Thiazide-mediated activation of phosphate secretion as principal treatment"],"answer":"C","whyOptions":["May worsen mineral disturbance.","Not the mechanism.","Binders can reduce absorption; choice requires assessment.","Not the standard mechanism."],"explain":"Binders can reduce absorption; choice requires assessment."},{"number":5,"q":"Which patient-centred action is most appropriate when adherence is limited by transport cost?","type":"SBA","options":["Recommend an expensive restrictive diet without assessment","Label the patient noncompliant and stop monitoring","Intensify treatment without checking access or understanding","Explore barriers and coordinate accessible follow-up, medication and nutrition counselling"],"answer":"D","whyOptions":["May be unaffordable and nutritionally harmful.","Fails to address barriers.","Risks poor implementation.","Addresses health system and social determinants."],"explain":"Addresses health system and social determinants."},{"number":6,"q":"Which interpretation best distinguishes this profile from nutritional vitamin D deficiency?","context":"Further mineral profile:\n25(OH)D (nmol/L): 75  (Reference: 50–125 (illustrative))\n1,25(OH)₂D (pmol/L): 20  (Reference: 48–190 (assay-dependent))\nPhosphate (mmol/L): 2.10  (Reference: 0.80–1.45)","isData":true,"type":"SBA","options":["Primary hyperparathyroidism with high serum calcium","Renal activation impairment with phosphate retention despite preserved substrate","Isolated nutritional vitamin D depletion with preserved renal activation","Uncomplicated osteoporosis with normal mineral regulation"],"answer":"B","whyOptions":["Calcium is low.","CKD reduces active vitamin D production; nutritional deficiency often has low 25(OH)D and low phosphate.","25(OH)D is preserved and renal function reduced.","Marked PTH and phosphate abnormalities are present."],"explain":"CKD reduces active vitamin D production; nutritional deficiency often has low 25(OH)D and low phosphate."},{"number":7,"q":"What is the active vitamin D metabolite called?","type":"VSAQ","options":[],"answer":"Calcitriol","accepted":["1 25 dihydroxyvitamin D","1,25(OH)2D"],"explain":"Calcitriol promotes intestinal calcium and phosphate absorption."},{"number":8,"q":"What term describes compensatory PTH elevation due to renal mineral disturbance?","type":"VSAQ","options":[],"answer":"Secondary hyperparathyroidism","accepted":[],"explain":"Chronic renal failure can drive compensatory PTH elevation."}]},{"id":94025,"title":"Dark urine after skin infection","core":["Nephritic syndrome"],"module":"Renal","scenario":"A 10-year-old boy develops facial puffiness, reduced urine output and cola-coloured urine three weeks after crusted skin sores. He has headaches and basal crackles. There is no dysuria or flank colic.","labContext":"BP (mmHg): 154/102  (Reference: Age/height dependent; markedly elevated)\nCreatinine (µmol/L): 142  (Reference: 30–70 (illustrative age-specific))\nAlbumin (g/L): 33  (Reference: 35–50)\nUrine dipstick: Blood 3+, protein 2+  (Reference: Negative)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 42–56; Guide p. 341; Paper 2 practice cluster 10","questions":[{"number":1,"q":"Which feature most strongly favours inflammatory glomerular disease over primary podocyte protein leak?","type":"SBA","options":["Cola-coloured urine with significant hypertension and oliguria","Periorbital oedema alone","Mildly reduced albumin alone","Recent infection alone"],"answer":"A","whyOptions":["Suggests glomerular haematuria and sodium retention; microscopy helps localise.","Seen in both nephritic and nephrotic syndromes.","Nonspecific.","Both can follow infections."],"explain":"Suggests glomerular haematuria and sodium retention; microscopy helps localise."},{"number":2,"q":"Which mechanism best explains the delayed renal symptoms after skin infection?","type":"SBA","options":["Direct bacterial invasion of renal tubules","Immune complex-associated glomerular inflammation with complement activation","IgE-mediated mast-cell degranulation in glomeruli","Primary genetic loss of slit diaphragm proteins"],"answer":"B","whyOptions":["Would favour pyelonephritis.","Post-streptococcal glomerulonephritis follows a latent interval.","Not the typical mechanism.","More often causes heavy proteinuria."],"explain":"Post-streptococcal glomerulonephritis follows a latent interval."},{"number":3,"q":"Why does GFR fall in the inflammatory process?","type":"SBA","options":["Endocapillary inflammation reduces effective filtration surface and permeability","Reduced Bowman's space pressure opposes filtration","Increased filtration surface from podocyte proliferation","Reduced capillary oncotic pressure opposes filtration"],"answer":"A","whyOptions":["Cellular swelling and proliferation compromise capillary filtration.","Reduced pressure favours filtration.","Not characteristic.","Would favour filtration."],"explain":"Cellular swelling and proliferation compromise capillary filtration."},{"number":4,"q":"Which mechanism best explains hypertension and crackles?","type":"SBA","options":["Reduced renal sodium and water excretion expands circulating volume","Increased GFR increases urinary salt loss","Renal salt wasting causes severe hypovolaemia","Severe hypoalbuminaemia causes isolated underfilling"],"answer":"A","whyOptions":["Nephritic sodium retention causes oedema and hypertension.","GFR is reduced.","Does not fit clinical findings.","Albumin is only mildly reduced; hypertension suggests expansion."],"explain":"Nephritic sodium retention causes oedema and hypertension."},{"number":5,"q":"He develops severe headache, blurred vision and confusion with BP 176/118. Which action is safest?","type":"SBA","options":["Give unrestricted IV fluids for oliguria","Wait for complement results before managing hypertension","Discharge with dietary salt advice","Urgent assessment for hypertensive emergency and supervised escalation"],"answer":"D","whyOptions":["May worsen volume overload.","Delays urgent care.","Unsafe.","Neurological symptoms with severe hypertension indicate possible target-organ injury."],"explain":"Neurological symptoms with severe hypertension indicate possible target-organ injury."},{"number":6,"q":"Which interpretation integrates timing, complement and sediment?","context":"Additional data:\nUrine microscopy: Dysmorphic RBCs and RBC casts  (Reference: Absent)\nProtein (g/day): 1.2  (Reference: \u003c0.15 (adult comparison))\nC3: Reduced  (Reference: Lab-specific normal)\nC4: Normal  (Reference: Lab-specific normal)\nAnti-DNase B: Elevated  (Reference: Age/assay-specific)","isData":true,"type":"SBA","options":["Acute interstitial nephritis with sterile pyuria","Minimal change disease with isolated protein leak","IgA nephropathy occurring during mucosal infection","Post-streptococcal glomerulonephritis with complement consumption"],"answer":"D","whyOptions":["Would not explain typical red cell casts and low C3 as well.","Typically nephrotic pattern and bland sediment.","Typically concurrent or soon after infection and normal complement.","Delayed skin infection, low C3 and nephritic sediment are supportive."],"explain":"Delayed skin infection, low C3 and nephritic sediment are supportive."},{"number":7,"q":"Which hypersensitivity category best describes immune complex-mediated injury?","type":"VSAQ","options":[],"answer":"Type III","accepted":["type 3","III","3","type III hypersensitivity","immune complex hypersensitivity"],"explain":"Immune complex deposition/formation activates inflammatory pathways."},{"number":8,"q":"Which urinary cast most strongly localises bleeding to the glomerulus?","type":"VSAQ","options":[],"answer":"Red cell cast","accepted":["red cell casts","RBC casts","RBC cast","erythrocyte casts"],"explain":"RBCs incorporated into tubular casts suggest glomerular bleeding."}]},{"id":94026,"title":"Haematuria with systemic symptoms","core":["Nephritic syndrome"],"module":"Renal","scenario":"A 24-year-old woman develops ankle swelling, dark urine and fatigue. She reports photosensitive facial rash, mouth ulcers and intermittent small-joint pain. Her blood pressure is raised. There are no urinary tract symptoms.","labContext":"BP (mmHg): 158/98  (Reference: Approx. 90–120/60–80)\nCreatinine (µmol/L): 185  (Reference: 45–90)\nAlbumin (g/L): 29  (Reference: 35–50)\nUrine protein: 3+  (Reference: Negative)\nUrine blood: 3+  (Reference: Negative)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 42–56; Guide pp. 317, 341; official examples/style","questions":[{"number":1,"q":"Which mechanism best integrates systemic autoimmune features with renal injury?","type":"SBA","options":["Immune complex formation and complement-mediated glomerular inflammation","Primary isolated podocyte effacement without inflammation","Direct ureteric obstruction by crystals","Isolated bacterial tubular invasion"],"answer":"A","whyOptions":["Lupus nephritis commonly involves immune complex deposition.","Can cause nephrosis but not the whole systemic pattern.","Does not explain rash and immune features.","Does not integrate systemic autoimmune features."],"explain":"Lupus nephritis commonly involves immune complex deposition."},{"number":2,"q":"Which urine feature best establishes an active glomerular inflammatory sediment?","type":"SBA","options":["Isolated calcium oxalate crystals","Hyaline casts alone","Dysmorphic erythrocytes and red cell casts","Squamous epithelial cells"],"answer":"C","whyOptions":["Suggests crystalluria but not glomerulitis.","Nonspecific.","Supports glomerular bleeding.","Often contamination."],"explain":"Supports glomerular bleeding."},{"number":3,"q":"Why may both nephritic and nephrotic features coexist?","type":"SBA","options":["Nephrotic proteinuria proves absence of inflammation","Glomerular inflammation can impair filtration and disrupt protein selectivity","Haematuria indicates only lower urinary tract injury","Reduced GFR prevents any albumin leak"],"answer":"B","whyOptions":["Inflammatory disease can produce heavy proteinuria.","Syndromes overlap when capillary barrier injury is substantial.","Glomerular disease can cause haematuria.","Barrier permeability can still be abnormal."],"explain":"Syndromes overlap when capillary barrier injury is substantial."},{"number":4,"q":"Which laboratory finding supports active immune complex disease in this setting?","type":"SBA","options":["Rising anti-dsDNA with reduced complement","Elevated TSH alone","Increased serum lipase","Isolated increased HbA₂"],"answer":"A","whyOptions":["Supports active lupus in context; not diagnostic alone.","Does not support this mechanism.","Not relevant to glomerular autoimmunity.","Suggests beta-thalassaemia trait."],"explain":"Supports active lupus in context; not diagnostic alone."},{"number":5,"q":"Her creatinine rises rapidly over days. Which action is appropriate?","type":"SBA","options":["Begin high-dose immunosuppression independently without assessing infection","Urgent renal assessment for rapidly progressive glomerular injury and possible biopsy","Wait three months before assessing further","Reassure because she is young"],"answer":"B","whyOptions":["Unsafe and beyond GEMP1 role.","Rapid deterioration needs specialist evaluation and supervised treatment.","Unsafe with rapidly worsening function.","Age does not exclude severe disease."],"explain":"Rapid deterioration needs specialist evaluation and supervised treatment."},{"number":6,"q":"Which interpretation best integrates the profile?","context":"Results:\nC3 and C4: Both low  (Reference: Lab-specific normal)\nAnti-dsDNA: Strongly positive  (Reference: Negative)\nProtein (g/day): 3.8  (Reference: \u003c0.15)\nMicroscopy: RBC casts  (Reference: Absent)","isData":true,"type":"SBA","options":["Immune-mediated glomerulonephritis with nephritic–nephrotic overlap","Pre-renal dysfunction with preserved glomerular barrier","Pure nephrotic syndrome with no inflammatory injury","Isolated lower tract bleeding with incidental autoimmune serology"],"answer":"A","whyOptions":["Active sediment and heavy protein loss can coexist in lupus nephritis.","Heavy proteinuria and casts argue against pure haemodynamic injury.","RBC casts and low complement indicate inflammation.","Does not explain casts and heavy proteinuria."],"explain":"Active sediment and heavy protein loss can coexist in lupus nephritis."},{"number":7,"q":"Name the crescent-forming epithelial cell type in severe glomerular injury.","type":"VSAQ","options":[],"answer":"Parietal epithelial cells","accepted":["parietal epithelial cell"],"explain":"Proliferation of parietal epithelial cells with inflammatory components can form crescents."},{"number":8,"q":"Which autoantibody is directed against double-stranded DNA?","type":"VSAQ","options":[],"answer":"Anti-dsDNA","accepted":["anti dsDNA","anti double stranded DNA","anti-dsDNA antibody"],"explain":"Anti-dsDNA is associated with SLE and may track renal activity."}]},{"id":94027,"title":"Puffy eyes in a young child","core":["Nephrotic syndrome"],"module":"Renal","scenario":"A 6-year-old boy develops morning eyelid swelling followed by leg oedema and abdominal distension after a mild respiratory illness. His urine is frothy but not visibly bloody. He has no fever, rash or joint symptoms. BP is appropriate for age; lungs are clear.","labContext":"Albumin (g/L): 17  (Reference: 35–50)\nCreatinine (µmol/L): 36  (Reference: 20–50 (illustrative age-specific))\nUrine protein: 4+  (Reference: Negative)\nUrine blood: Negative  (Reference: Negative)\nCholesterol (mmol/L): 8.1  (Reference: \u003c5 desirable (illustrative))","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 32–41; Guide p. 342; 2026 GEMP 2 Cases p. 4","questions":[{"number":1,"q":"Which finding most strongly distinguishes this syndrome from nephritic disease?","type":"SBA","options":["Facial oedema","Recent respiratory illness","Young age","Marked proteinuria with hypoalbuminaemia and no active haematuria"],"answer":"D","whyOptions":["Shared feature.","Both syndromes can follow infection.","Does not by itself distinguish syndromes.","Nephrotic pattern dominates."],"explain":"Nephrotic pattern dominates."},{"number":2,"q":"Which ultrastructural abnormality is typical of childhood minimal change disease?","type":"SBA","options":["Endocapillary neutrophil proliferation","Crescent formation in Bowman's space","Diffuse podocyte foot process effacement","Nodular mesangial matrix expansion"],"answer":"C","whyOptions":["Typical of inflammatory glomerulonephritis.","Severe inflammatory injury.","Electron microscopy demonstrates effacement despite little light microscopy change.","Characteristic of diabetic nephropathy."],"explain":"Electron microscopy demonstrates effacement despite little light microscopy change."},{"number":3,"q":"In the underfill model, why does sodium retention occur despite oedema?","type":"SBA","options":["Increased effective arterial volume stimulates renin","Reduced oncotic pressure lowers effective circulating volume and activates RAAS","Increased plasma oncotic pressure activates aldosterone","Proteinuria directly increases atrial natriuretic peptide-mediated sodium retention"],"answer":"B","whyOptions":["Would suppress renin.","Fluid shifts out of vascular space; primary renal sodium retention is another mechanism.","Oncotic pressure is reduced.","ANP generally promotes natriuresis."],"explain":"Fluid shifts out of vascular space; primary renal sodium retention is another mechanism."},{"number":4,"q":"Which loss contributes to increased susceptibility to bacterial infection?","type":"SBA","options":["Increased urinary neutrophil production","Urinary immunoglobulin loss","Urinary loss of thromboxane alone","Urinary loss of haemoglobin-bound oxygen"],"answer":"B","whyOptions":["Not characteristic mechanism.","Loss of IgG and other defence factors impairs humoral immunity.","Not a major antibody defence mechanism.","Does not explain susceptibility."],"explain":"Loss of IgG and other defence factors impairs humoral immunity."},{"number":5,"q":"His mother asks whether dialysis will be needed. What response is most appropriate?","type":"SBA","options":["Explain many children respond to treatment, while further assessment is needed to establish prognosis","Avoid all discussion until specialist review","State dialysis is likely because oedema is extensive","Promise that dialysis is impossible"],"answer":"A","whyOptions":["Balances realistic reassurance and uncertainty.","Unnecessarily dismisses concerns.","Oedema does not establish kidney failure.","Cannot guarantee outcomes."],"explain":"Balances realistic reassurance and uncertainty."},{"number":6,"q":"Which interpretation best fits?","context":"Further results:\nUrine protein:creatinine (mg/mmol): 420  (Reference: \u003c20 (illustrative child; nephrotic range ≥200))\nC3: Normal  (Reference: Lab-specific normal)\nMicroscopy: No RBC casts; oval fat bodies  (Reference: No abnormal casts/lipiduria)","isData":true,"type":"SBA","options":["Postinfectious nephritic disease with active sediment","Reduced hepatic albumin synthesis without renal loss","Predominant nephrotic protein barrier dysfunction with preserved filtration","Proximal tubular low-molecular-weight protein loss only"],"answer":"C","whyOptions":["RBC casts and complement consumption are not present.","Urine protein is marked.","Heavy protein loss, lipiduria and normal creatinine fit.","Magnitude and hypoalbuminaemia favour glomerular leak."],"explain":"Heavy protein loss, lipiduria and normal creatinine fit."},{"number":7,"q":"Which drug class is used under supervision in typical steroid-sensitive childhood nephrotic syndrome?","type":"VSAQ","options":[],"answer":"Corticosteroids","accepted":["glucocorticoids","steroids","prednisone","prednisolone"],"explain":"Many childhood cases respond to glucocorticoids after appropriate assessment."},{"number":8,"q":"Which coagulation inhibitor can be lost in urine, contributing to thrombosis?","type":"VSAQ","options":[],"answer":"Antithrombin","accepted":["antithrombin III","ATIII","AT III"],"explain":"Loss of anticoagulant proteins contributes to nephrotic hypercoagulability."}]},{"id":94028,"title":"Generalised oedema with sudden pleuritic pain","core":["Nephrotic syndrome"],"module":"Renal","scenario":"A 35-year-old woman with untreated HIV presents with progressive swelling, foamy urine and ascites. She has no orthopnoea and normal JVP. She is afebrile. Two days after admission, she develops pleuritic chest pain and shortness of breath.","labContext":"Albumin (g/L): 18  (Reference: 35–50)\nUrine protein (g/day): 6.8  (Reference: \u003c0.15; nephrotic >3.5)\nCreatinine (µmol/L): 98  (Reference: 45–90)\nCholesterol (mmol/L): 9.0  (Reference: \u003c5 desirable)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 32–41, systemic disease section; Guide p. 342","questions":[{"number":1,"q":"Which mechanism directly permits large albumin losses despite relatively preserved filtration of small solutes?","type":"SBA","options":["Isolated obstruction of urinary outflow","Disruption of podocyte slit diaphragm and filtration barrier selectivity","Increased hepatic albumin synthesis","Increased tubular secretion of albumin"],"answer":"B","whyOptions":["Not the characteristic heavy protein leak mechanism.","Glomerular protein permeability increases even when GFR is relatively maintained.","Does not cause marked urinary loss.","Albumin is not normally secreted this way."],"explain":"Glomerular protein permeability increases even when GFR is relatively maintained."},{"number":2,"q":"Which mechanism contributes to hyperlipidaemia?","type":"SBA","options":["Reduced intestinal fat absorption as the principal cause","Increased urinary cholesterol clearance alone","Reduced hepatic lipid synthesis and increased uptake","Increased hepatic lipoprotein production and impaired lipid clearance"],"answer":"D","whyOptions":["Does not explain high circulating lipids.","Would tend to lower circulating lipids.","Opposite pattern.","Nephrotic disease alters both production and clearance."],"explain":"Nephrotic disease alters both production and clearance."},{"number":3,"q":"Why is a pulmonary thromboembolic complication a concern?","type":"SBA","options":["IgG loss directly causes pulmonary vasospasm","Urinary loss of endogenous anticoagulants with prothrombotic changes","Urinary loss of fibrinogen causing isolated haemorrhage","Reduced platelet activity from albumin loss"],"answer":"B","whyOptions":["IgG loss contributes to infection risk.","Nephrotic syndrome increases venous thrombosis risk.","Does not explain thrombosis.","Not the principal prothrombotic mechanism."],"explain":"Nephrotic syndrome increases venous thrombosis risk."},{"number":4,"q":"What is the safest response to abrupt hypoxaemia and pleuritic pain?","type":"SBA","options":["Independently give anticoagulation before assessing bleeding risk","Urgent ABC assessment, oxygen as indicated and escalation for thromboembolism evaluation","Give diuretics alone and reassess tomorrow","Reassure because creatinine is preserved"],"answer":"B","whyOptions":["Requires supervised assessment.","Do not assume oedema explains all dyspnoea.","May miss embolic emergency.","GFR does not eliminate thrombotic risk."],"explain":"Do not assume oedema explains all dyspnoea."},{"number":5,"q":"Which approach to her HIV disclosure respects patient-centred care?","type":"SBA","options":["Attribute all renal disease to HIV without further assessment","Inform household members without permission as routine","Obtain consent, protect confidentiality and coordinate HIV and renal care","Withhold renal care until antiretroviral adherence is established"],"answer":"C","whyOptions":["Multiple causes possible.","Breaches confidentiality absent valid exceptions.","Treatment access and respectful discussion are important.","Unsafe and discriminatory."],"explain":"Treatment access and respectful discussion are important."},{"number":6,"q":"Which interpretation best localises the protein loss?","context":"Urine and serum findings:\nRBC per HPF: 0–2  (Reference: 0–2)\nOval fat bodies: Present  (Reference: Absent)\nAlbumin (g/L): 18  (Reference: 35–50)\n24 h urine protein (g): 6.8  (Reference: \u003c0.15)","isData":true,"type":"SBA","options":["Pure nephritic inflammation with active RBC casts","Hepatic synthetic failure as sole cause of oedema","Glomerular nephrotic pattern with lipiduria","Tubular protein leak alone with no glomerular abnormality"],"answer":"C","whyOptions":["Not demonstrated.","Does not explain marked urine protein.","Heavy albumin loss and oval fat bodies support nephrotic syndrome.","Magnitude argues against isolated tubular proteinuria."],"explain":"Heavy albumin loss and oval fat bodies support nephrotic syndrome."},{"number":7,"q":"Which glomerular cell produces the foot processes forming filtration slits?","type":"VSAQ","options":[],"answer":"Podocyte","accepted":["podocytes"],"explain":"Podocytes form a critical component of the filtration barrier."},{"number":8,"q":"Which membrane is shared by glomerular endothelium and podocytes?","type":"VSAQ","options":[],"answer":"Glomerular basement membrane","accepted":["GBM"],"explain":"The GBM is an important structural and selective filtration component."}]},{"id":94029,"title":"Sudden loin-to-groin pain","core":["Renal Calculi"],"module":"Renal","scenario":"A 36-year-old outdoor worker develops severe left flank pain radiating to the groin, with nausea and restlessness. He drinks little water during shifts. He has no fever or dysuria. Renal angle tenderness is present without peritonism.","labContext":"Temperature (°C): 36.8  (Reference: 36.5–37.5)\nCreatinine (µmol/L): 101  (Reference: 60–110)\nUrine blood: 3+  (Reference: Negative)\nUrine pH: 5.8  (Reference: 4.5–8.0)\nSerum Ca (mmol/L): 2.42  (Reference: 2.20–2.60)","difficulty":"Challenge","difficultyRating":3,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 174–185; Guide p. 343; recalled 2026 cases p. 4","questions":[{"number":1,"q":"Which mechanism best explains the fluctuating intensity of pain?","type":"SBA","options":["Parietal peritoneal inflammation causing pain with every movement","Ureteric smooth muscle contraction against obstruction with increased intraluminal pressure","Isolated renal arterial spasm causing cortical infarction","Glomerular immune injury causing inflammatory capsular pain"],"answer":"B","whyOptions":["Peritonism causes guarding and reluctance to move.","Peristalsis and distension cause colicky visceral pain.","Less consistent with typical radiation and restlessness.","Does not typically produce loin-to-groin colic."],"explain":"Peristalsis and distension cause colicky visceral pain."},{"number":2,"q":"Why is microscopic haematuria common?","type":"SBA","options":["Increased urinary bilirubin mimics intact RBCs","Immune complex-mediated glomerular basement membrane injury","Inhibition of erythropoietin release increases urinary RBCs","Calculus abrasion and injury to urothelium"],"answer":"D","whyOptions":["Different test finding.","Would produce glomerular sediment.","EPO affects marrow production, not urinary bleeding.","Mechanical mucosal injury releases RBCs."],"explain":"Mechanical mucosal injury releases RBCs."},{"number":3,"q":"How can NSAIDs relieve renal colic in an appropriate patient?","type":"SBA","options":["Direct dissolution of calcium-containing crystals","Increased afferent vasodilatation raises urine flow through obstruction","Muscarinic agonism increases ureteric contraction","Reduced prostaglandin synthesis decreases inflammatory sensitisation and renal pelvic pressure"],"answer":"D","whyOptions":["NSAIDs do not dissolve stones.","NSAIDs reduce prostaglandin-mediated dilatation.","Not the principal action.","COX inhibition can reduce pain and pressure, but renal and GI risks must be reviewed."],"explain":"COX inhibition can reduce pain and pressure, but renal and GI risks must be reviewed."},{"number":4,"q":"Which prevention strategy is physiologically sound for common calcium oxalate stones?","type":"SBA","options":["Increase urine volume, maintain normal dietary calcium and review sodium intake","Restrict water to lower glomerular pressure chronically","Increase dietary sodium to reduce urinary calcium","Eliminate dietary calcium completely"],"answer":"A","whyOptions":["Normal dietary calcium binds intestinal oxalate; avoid indiscriminate restriction.","Low volume increases supersaturation.","High sodium can increase calciuria.","May increase intestinal oxalate absorption."],"explain":"Normal dietary calcium binds intestinal oxalate; avoid indiscriminate restriction."},{"number":5,"q":"Which new finding most strongly changes the urgency of a stone presentation?","type":"SBA","options":["Fever with hypotension and obstructed collecting system","Persistent microscopic haematuria alone","Pain improving after analgesia alone","Normal calcium concentration"],"answer":"A","whyOptions":["Infected obstruction requires urgent antibiotics, resuscitation and drainage assessment.","Common in uncomplicated stone, requires follow-up but less urgent.","Does not prove passage but not immediate sepsis signal.","Does not exclude stone."],"explain":"Infected obstruction requires urgent antibiotics, resuscitation and drainage assessment."},{"number":6,"q":"Which stone composition fits the crystal morphology and context?","context":"CT and microscopy:\nCT: 4 mm distal ureteric calculus; mild hydronephrosis  (Reference: No calculus or dilation)\nCrystal shape: Envelope-shaped  (Reference: Variable; none expected)\nUrine culture: No growth  (Reference: No growth)","isData":true,"type":"SBA","options":["Cystine","Magnesium ammonium phosphate","Calcium oxalate","Uric acid"],"answer":"C","whyOptions":["Typically hexagonal crystals.","Often coffin-lid crystals with urease infection and alkaline urine.","Typical envelope-shaped dihydrate crystals; composition confirmed by stone analysis.","Often rhomboid crystals in acidic urine."],"explain":"Typical envelope-shaped dihydrate crystals; composition confirmed by stone analysis."},{"number":7,"q":"Which urinary molecule complexes calcium and inhibits crystal formation?","type":"VSAQ","options":[],"answer":"Citrate","accepted":["urinary citrate"],"explain":"Reduces free calcium available for precipitation."},{"number":8,"q":"Which epithelial lining is injured to produce this patient's haematuria?","type":"VSAQ","options":[],"answer":"Urothelium","accepted":["transitional epithelium","ureteric urothelium","ureteral urothelium"],"explain":"Urothelial abrasion from the stone produces bleeding."}]},{"id":94030,"title":"Recurrent infection and a branching calculus","core":["Renal Calculi"],"module":"Renal","scenario":"A 46-year-old woman has recurrent dysuria and antibiotic courses over eight months. She now has fever, flank pain and nausea. Prior cultures repeatedly grew a urease-positive Gram-negative bacillus. Ultrasound demonstrates a branching echogenic lesion occupying the renal pelvis and calyces.","labContext":"Temperature (°C): 38.6  (Reference: 36.5–37.5)\nWCC (×10⁹/L): 15.8  (Reference: 4–11)\nCreatinine (µmol/L): 142  (Reference: 45–90)\nUrine pH: 8.7  (Reference: 4.5–8.0)\nUrine nitrites: Positive  (Reference: Negative)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 174–199; Guide p. 343","questions":[{"number":1,"q":"Which reaction increases urinary pH?","type":"SBA","options":["Nitrate reduction generates the principal alkaline buffer","Glucose fermentation generates organic acids","Uric acid synthesis directly produces ammonium","Urease hydrolyses urea to ammonia and carbon dioxide"],"answer":"D","whyOptions":["Explains nitrite positivity, not principal alkalinisation.","Would tend to lower pH.","Not the bacterial mechanism.","Ammonia accepts protons and alkalinises urine."],"explain":"Ammonia accepts protons and alkalinises urine."},{"number":2,"q":"Which stone composition is favoured by alkaline ammonium-rich urine?","type":"SBA","options":["Calcium oxalate","Cystine","Magnesium ammonium phosphate","Uric acid"],"answer":"C","whyOptions":["Not specifically associated with urease activity.","Inherited transport disorder; acidic urine favours precipitation.","Struvite is associated with urease-producing infection.","Typically favoured by acidic urine."],"explain":"Struvite is associated with urease-producing infection."},{"number":3,"q":"Why can infection recur after apparently appropriate antibiotics?","type":"SBA","options":["Sterile casts reproduce bacteria independently","Ureteric contraction directly causes antibiotic resistance","Antibiotics convert glomerular immune complexes into bacteria","Stone-associated biofilm can harbour persistent bacteria"],"answer":"D","whyOptions":["Casts do not generate organisms.","Not the principal explanation.","Incorrect mechanism.","A reservoir remains until source is adequately addressed."],"explain":"A reservoir remains until source is adequately addressed."},{"number":4,"q":"Which change reduces GFR if drainage is blocked?","type":"SBA","options":["Increased capillary hydrostatic pressure","Reduced glomerular oncotic pressure","Reduced Bowman's space pressure","Increased hydrostatic pressure in Bowman's space"],"answer":"D","whyOptions":["Typically favours filtration.","Favours filtration.","Favours filtration.","Back pressure opposes filtration."],"explain":"Back pressure opposes filtration."},{"number":5,"q":"She becomes confused and hypotensive, with hydronephrosis. What is the safest approach?","type":"SBA","options":["Antibiotics alone until fever resolves","Urgent sepsis resuscitation, IV antibiotics and escalation for drainage","Oral fluid and expulsive treatment alone","Immediate stone fragmentation before resuscitation"],"answer":"B","whyOptions":["Obstruction must be urgently addressed.","Infected obstruction is a urological emergency requiring source control.","Unsafe with shock.","Definitive removal is usually deferred until sepsis controlled."],"explain":"Infected obstruction is a urological emergency requiring source control."},{"number":6,"q":"Which organism best fits this profile?","context":"Culture findings:\nGram stain: Gram-negative rods  (Reference: No organisms)\nUrease: Strong positive  (Reference: Organism-dependent)\nOxidase: Negative  (Reference: Organism-dependent)\nLactose fermentation: Negative  (Reference: Organism-dependent)\nGrowth: Swarming  (Reference: Organism-dependent)","isData":true,"type":"SBA","options":["Pseudomonas aeruginosa","Proteus mirabilis","Klebsiella pneumoniae","Escherichia coli"],"answer":"B","whyOptions":["Usually oxidase-positive, not classic Proteus swarming.","Urease-positive, swarming, non-lactose-fermenting organism associated with struvite.","Typically lactose-fermenting and nonmotile.","Usually lactose-fermenting and urease-negative."],"explain":"Urease-positive, swarming, non-lactose-fermenting organism associated with struvite."},{"number":7,"q":"What term describes a branching calculus filling the renal pelvis and multiple calyces?","type":"VSAQ","options":[],"answer":"Staghorn calculus","accepted":["staghorn stone","staghorn","stag horn calculus"],"explain":"A staghorn shape is common in infection stones but is not composition-specific."},{"number":8,"q":"Name the direct percutaneous drainage procedure that may relieve an infected obstructed kidney.","type":"VSAQ","options":[],"answer":"Percutaneous nephrostomy","accepted":["nephrostomy","PCN"],"explain":"Provides collecting system drainage; ureteric stenting is another possible approach."}]},{"id":94031,"title":"Profuse stools despite fasting","core":["Diarrhoea"],"module":"GIT","scenario":"A 33-year-old man presents with abrupt profuse watery stools following a disruption of the local water supply. Several neighbours are ill. The diarrhoea continues even when he stops eating. He is thirsty, weak and unable to keep up with the fluid losses. His abdomen is soft, with no blood in stool or high fever.","labContext":"BP (mmHg): 84/52  (Reference: Approx. 90–120/60–80)\nHR (/min): 132  (Reference: 60–100)\nNa (mmol/L): 146  (Reference: 135–145)\nK (mmol/L): 2.9  (Reference: 3.5–5.1)\nHCO₃⁻ (mmol/L): 14  (Reference: 22–26)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 23, 30–31, 239–272; SV GIT; Guide p. 346","questions":[{"number":1,"q":"Which epithelial mechanism most directly produces toxin-mediated secretory diarrhoea in cholera-like illness?","type":"SBA","options":["Direct villous invasion with crypt abscesses","Increased intracellular cAMP stimulates CFTR-mediated chloride secretion","Reduced cAMP inhibits chloride secretion and increases luminal osmoles","Reduced pancreatic lipase secretion causes fat retention"],"answer":"B","whyOptions":["More typical of inflammatory diarrhoea.","Cholera toxin persistently activates Gs, raising cAMP and luminal chloride/water secretion.","Does not account for the characteristic secretory mechanism.","Produces malabsorption, not massive watery secretion."],"explain":"Cholera toxin persistently activates Gs, raising cAMP and luminal chloride/water secretion."},{"number":2,"q":"Why can stools continue when oral food is withheld?","type":"SBA","options":["Reduced luminal bile salts cause persistent fat maldigestion","Poorly absorbed dietary sugars continue entering lumen during fasting","Fasting directly increases mucosal ulceration","Active epithelial electrolyte secretion is independent of dietary osmotic substrate"],"answer":"D","whyOptions":["Does not explain massive secretion.","Removing the substrate usually reduces osmotic diarrhoea.","Not the defining mechanism.","Secretory diarrhoea continues during fasting."],"explain":"Secretory diarrhoea continues during fasting."},{"number":3,"q":"Which physiological mechanism permits glucose-containing ORS to remain useful once circulation is stabilised?","type":"SBA","options":["CFTR blockade by glucose directly stops secretion","Sodium–glucose cotransport remains functional despite chloride secretion","Direct passive glucose-mediated chloride efflux","Inhibition of basolateral Na⁺/K⁺-ATPase increases sodium absorption"],"answer":"B","whyOptions":["Not the mechanism.","SGLT1-mediated absorption can continue in secretory diarrhoea.","Not the basis of ORS.","Would impair the sodium gradient."],"explain":"SGLT1-mediated absorption can continue in secretory diarrhoea."},{"number":4,"q":"Which acid–base disturbance is predicted from ongoing bicarbonate-rich stool losses?","type":"SBA","options":["Metabolic acidosis from gastrointestinal bicarbonate loss","Primary respiratory alkalosis from reduced renal filtration","Primary respiratory acidosis from intestinal chloride secretion","Metabolic alkalosis from gastric hydrogen loss"],"answer":"A","whyOptions":["Often hyperchloraemic; shock can add lactic acidosis.","Not the primary mechanism.","Does not follow directly.","Stool bicarbonate loss has the opposite effect."],"explain":"Often hyperchloraemic; shock can add lactic acidosis."},{"number":5,"q":"Which supervised action addresses the immediate risk?","type":"SBA","options":["Oral antimotility treatment alone while hypotensive","Restrict fluid to reduce stool output","Wait for stool culture before beginning fluids","Urgent isotonic fluid resuscitation with reassessment, electrolyte replacement and public-health escalation"],"answer":"D","whyOptions":["Does not restore perfusion.","Worsens dehydration.","Dangerous delay.","Shock and profuse losses require prompt care and outbreak assessment."],"explain":"Shock and profuse losses require prompt care and outbreak assessment."},{"number":6,"q":"Which result best supports the mechanism?","context":"Stool electrolyte assessment:\nStool Na (mmol/L): 100  (Reference: Variable)\nStool K (mmol/L): 25  (Reference: Variable)\nOsmotic gap formula: 290 − 2(Na + K)  (Reference: \u003c50 supports secretory)","isData":true,"type":"SBA","options":["40 mOsm/kg; predominantly secretory","125 mOsm/kg; inflammatory","250 mOsm/kg; predominantly osmotic","165 mOsm/kg; predominantly osmotic"],"answer":"A","whyOptions":["290 − 250 = 40.","This is the sum, not the gap.","This is the electrolyte contribution, not the gap.","Incorrect subtraction of undoubled sum."],"explain":"290 − 250 = 40."},{"number":7,"q":"Which epithelial channel is activated downstream of cAMP in toxin-mediated chloride secretion?","type":"VSAQ","options":[],"answer":"CFTR","accepted":["cystic fibrosis transmembrane conductance regulator"],"explain":"CFTR provides apical chloride secretion."},{"number":8,"q":"Which epidemiological route links contaminated water to enteric disease?","type":"VSAQ","options":[],"answer":"Faecal oral","accepted":["fecal oral","faecal-oral transmission","fecal-oral transmission","waterborne transmission"],"explain":"Contamination of drinking water permits faecal–oral transmission."}]},{"id":94032,"title":"Fresh haematemesis in chronic liver disease","core":["Upper GI Bleed"],"module":"GIT","scenario":"A 51-year-old man with chronic liver disease vomits a large amount of fresh blood and passes black stools. He has ascites, spider naevi and splenomegaly. He is drowsy, cool and hypotensive. He previously missed follow-up for oesophageal varices.","labContext":"BP (mmHg): 82/48  (Reference: Approx. 90–120/60–80)\nHR (/min): 126  (Reference: 60–100)\nHb (g/dL): 8.0  (Reference: 13–17)\nPlatelets (×10⁹/L): 64  (Reference: 150–400)\nINR: 1.9  (Reference: 0.8–1.2)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 93–101, 186–202; Paper 2 Practice cluster 1; Guide pp. 354, 360","questions":[{"number":1,"q":"Which portosystemic connection explains the formation of distal oesophageal varices?","type":"SBA","options":["Left gastric vein and oesophageal veins draining towards azygos system","Inferior mesenteric vein and internal iliac veins at distal oesophagus","Hepatic artery and splenic vein","Superior mesenteric artery and portal vein"],"answer":"A","whyOptions":["Portal-systemic collaterals enlarge with portal hypertension.","Rectal collateral location, not oesophageal.","Not a normal portosystemic venous collateral.","Arterial-to-venous connection is not the typical variceal route."],"explain":"Portal-systemic collaterals enlarge with portal hypertension."},{"number":2,"q":"Why can a relatively modest increase in variceal diameter increase rupture risk?","type":"SBA","options":["Increased radius lowers tension at a given pressure","Increased radius raises wall tension at a given transmural pressure","Increased radius increases wall thickness proportionally in all cases","Increased radius eliminates portal pressure"],"answer":"B","whyOptions":["Opposite relation.","Laplace principle; thin distended venous walls are vulnerable.","Not a reliable protective adaptation.","Does not eliminate portal hypertension."],"explain":"Laplace principle; thin distended venous walls are vulnerable."},{"number":3,"q":"How does propranolol reduce portal inflow in a stable patient?","type":"SBA","options":["Selective α1 blockade directly constricts splanchnic vessels","β1 blockade increases output and β2 blockade causes vasodilatation","Direct fibrin degradation opens portal collaterals","β1 blockade reduces cardiac output and β2 blockade favours splanchnic vasoconstriction"],"answer":"D","whyOptions":["Alpha blockade generally vasodilates.","Opposite effects.","Not beta-blocker action.","Both mechanisms reduce portal inflow; review use during hypotension."],"explain":"Both mechanisms reduce portal inflow; review use during hypotension."},{"number":4,"q":"Which initial priority applies before definitive endoscopic therapy?","type":"SBA","options":["Arrange routine outpatient endoscopy","Correct INR to normal before all emergency care","Begin oral beta-blocker before assessing perfusion","Protect airway as needed, resuscitate circulation and urgently escalate"],"answer":"D","whyOptions":["Unsafe with active major bleeding.","Do not delay life-saving stabilisation.","May worsen hypotension.","Active haematemesis with altered consciousness and shock creates airway and circulatory danger."],"explain":"Active haematemesis with altered consciousness and shock creates airway and circulatory danger."},{"number":5,"q":"Which supervised therapy directly controls bleeding from identified oesophageal varices?","type":"SBA","options":["Endoscopic gastric polypectomy","ERCP with biliary sphincterotomy","Endoscopic variceal band ligation","Balloon dilation of oesophagus"],"answer":"C","whyOptions":["Does not treat varices.","Treats bile duct pathology.","Mechanical ligation controls variceal haemorrhage; acute management also includes appropriate vasoactive/antibiotic treatment.","Not a haemostatic intervention."],"explain":"Mechanical ligation controls variceal haemorrhage; acute management also includes appropriate vasoactive/antibiotic treatment."},{"number":6,"q":"Which explanation best integrates urea elevation with the bleeding?","context":"Following resuscitation, endoscopy finds large distal oesophageal varices with active bleeding; albumin 23 g/L (35–50), urea 16 mmol/L (2.5–7.8), creatinine 100 µmol/L (60–110).","isData":true,"type":"SBA","options":["Albumin loss causes direct renal conversion of creatinine to urea","Reduced hepatic urea synthesis directly raises urea","Normal creatinine excludes any haemodynamic renal insult","Digested blood adds nitrogen substrate for urea formation; hypoperfusion can contribute"],"answer":"D","whyOptions":["Incorrect physiology.","Reduced synthesis would lower production.","Early renal dysfunction may be masked by kinetics.","Urea may rise disproportionately in UGIB."],"explain":"Urea may rise disproportionately in UGIB."},{"number":7,"q":"Which nonselective beta-blocker is commonly used for portal hypertension prophylaxis?","type":"VSAQ","options":[],"answer":"Propranolol","accepted":["carvedilol","nadolol"],"explain":"Nonselective beta blockade reduces portal inflow; assess haemodynamic suitability."},{"number":8,"q":"Which venous system carries blood from most abdominal digestive organs to the liver?","type":"VSAQ","options":[],"answer":"Portal venous system","accepted":["portal system","hepatic portal system","portal vein"],"explain":"Portal venous blood passes through hepatic sinusoids before systemic drainage."}]},{"id":94033,"title":"Repeated nonbilious vomiting","core":["Peptic Ulcer Disease"],"module":"GIT","scenario":"A 48-year-old man with recurrent ulcer symptoms and NSAID exposure develops early satiety and vomiting of undigested food hours after meals. He is dehydrated and has a succussion splash several hours after eating. Vomit contains no bile.","labContext":"BP (mmHg): 94/60  (Reference: Approx. 90–120/60–80)\nK (mmol/L): 2.7  (Reference: 3.5–5.1)\nCl (mmol/L): 83  (Reference: 98–107)\nCreatinine (µmol/L): 158  (Reference: 60–110)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 82–92; SV GIT gastric physiology; Guide p. 353","questions":[{"number":1,"q":"Which structural process best accounts for the progressive gastric retention?","type":"SBA","options":["Isolated common bile duct stenosis","Primary distal colonic inflammation","Distal oesophageal fibrosis prevents swallowing","Repeated ulcer healing produces fibrotic pyloroduodenal narrowing"],"answer":"D","whyOptions":["Impairs bile drainage, not gastric emptying.","Does not explain proximal retention.","Would cause dysphagia rather than delayed vomiting of food.","Scarring may cause gastric outlet obstruction."],"explain":"Scarring may cause gastric outlet obstruction."},{"number":2,"q":"Which acid–base mechanism results directly from prolonged vomiting?","type":"SBA","options":["Renal retention of hydrogen ions causes metabolic acidosis","Loss of intestinal bicarbonate produces hyperchloraemic acidosis","Loss of gastric hydrochloric acid increases serum bicarbonate relative to chloride","Hyperventilation produces primary metabolic alkalosis"],"answer":"C","whyOptions":["Does not account for initial gastric losses.","More typical of diarrhoea.","HCl loss produces chloride-depletion metabolic alkalosis.","Hyperventilation causes respiratory alkalosis."],"explain":"HCl loss produces chloride-depletion metabolic alkalosis."},{"number":3,"q":"Why can hypokalaemia persist despite limited intake?","type":"SBA","options":["Gastric acid loss prevents renal potassium elimination","Reduced distal delivery directly increases potassium excretion in isolation","Suppressed aldosterone increases potassium secretion","Volume depletion stimulates aldosterone-mediated renal potassium secretion"],"answer":"D","whyOptions":["Does not explain ongoing renal losses.","Reduced flow tends to reduce secretion.","Opposite effect.","Secondary hyperaldosteronism and bicarbonaturia contribute to potassium loss."],"explain":"Secondary hyperaldosteronism and bicarbonaturia contribute to potassium loss."},{"number":4,"q":"Why may urine become acidic despite systemic alkalinaemia?","type":"SBA","options":["Respiratory compensation directly converts urine bicarbonate to glucose","Renal hydrogen retention makes urine more acidic","Kidneys excrete large amounts of bicarbonate causing acidic urine","Severe volume and potassium depletion favour renal hydrogen secretion"],"answer":"D","whyOptions":["Incorrect mechanism.","Opposite relationship.","Bicarbonate excretion makes urine alkaline.","Paradoxical aciduria can maintain alkalosis."],"explain":"Paradoxical aciduria can maintain alkalosis."},{"number":5,"q":"Which supervised management priority fits this presentation?","type":"SBA","options":["Fluid restriction with loop diuretics","Oral prokinetic alone before excluding mechanical obstruction","IV bicarbonate to correct low chloride","Reassessed isotonic saline and electrolyte correction, gastric decompression and urgent evaluation"],"answer":"D","whyOptions":["Worsens volume and chloride depletion.","May be inappropriate in obstruction.","Worsens alkalosis.","Addresses chloride/volume loss and obstruction."],"explain":"Addresses chloride/volume loss and obstruction."},{"number":6,"q":"Which acid–base interpretation fits?","context":"ABG and urine:\npH: 7.52  (Reference: 7.35–7.45)\nHCO₃⁻ (mmol/L): 36  (Reference: 22–26)\nPaCO₂ (mmHg): 48  (Reference: 35–45)\nUrine chloride (mmol/L): 8  (Reference: \u003c20 supports chloride depletion in context)","isData":true,"type":"SBA","options":["Metabolic acidosis with respiratory alkalosis","Respiratory acidosis with fully compensated pH","Metabolic alkalosis with appropriate respiratory compensation","Metabolic alkalosis with primary respiratory alkalosis"],"answer":"C","whyOptions":["Bicarbonate is elevated.","Primary alkalinaemia and raised bicarbonate indicate metabolic alkalosis.","Expected PaCO₂ approximately 48; low urine chloride supports chloride-responsive alkalosis.","PaCO₂ is elevated, not reduced."],"explain":"Expected PaCO₂ approximately 48; low urine chloride supports chloride-responsive alkalosis."},{"number":7,"q":"Name the electrolyte-responsive form of alkalosis suggested by a low urine chloride.","type":"VSAQ","options":[],"answer":"Chloride responsive alkalosis","accepted":["chloride sensitive alkalosis","saline responsive alkalosis","chloride depletion alkalosis","contraction alkalosis"],"explain":"Volume/chloride replacement helps restore renal bicarbonate excretion."},{"number":8,"q":"Which anatomical region connects stomach to the first part of duodenum?","type":"VSAQ","options":[],"answer":"Pylorus","accepted":["pyloric canal","pyloric sphincter"],"explain":"Scarring around the outlet can impede gastric emptying."}]},{"id":94034,"title":"Weight loss and oily stools after recurrent pain","core":["Pancreatitis"],"module":"GIT","scenario":"A 52-year-old man with years of heavy alcohol use has recurrent epigastric pain and progressive weight loss. His stools are greasy, bulky and difficult to flush. More recently he reports thirst and polyuria. Examination reveals muscle wasting without jaundice.","labContext":"Albumin (g/L): 31  (Reference: 35–50)\nFasting glucose (mmol/L): 9.8  (Reference: 3.9–5.5)\nLipase (U/L): 40  (Reference: 13–60)\nBMI (kg/m²): 18.2  (Reference: 18.5–24.9)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 203–221; Guide p. 359; SV GIT pancreatic physiology","questions":[{"number":1,"q":"Which histopathological process best integrates the digestive and endocrine symptoms?","type":"SBA","options":["Isolated gallbladder inflammation with intact pancreatic function","Reversible isolated duct oedema with preserved acini and islets","Progressive pancreatic fibrosis with loss of acinar and islet tissue","Primary villous atrophy with intact pancreas"],"answer":"C","whyOptions":["Not the best fit.","Does not account for chronic maldigestion and dysglycaemia.","Chronic injury impairs both exocrine and endocrine function.","May cause malabsorption but does not explain recurrent pancreatic pain and calcification."],"explain":"Chronic injury impairs both exocrine and endocrine function."},{"number":2,"q":"Which enzyme deficiency most directly causes steatorrhoea?","type":"SBA","options":["Pancreatic lipase deficiency","Pepsin deficiency","Brush-border lactase deficiency","Pancreatic amylase deficiency"],"answer":"A","whyOptions":["Reduces triglyceride digestion.","Impairs gastric protein digestion.","Causes carbohydrate-related osmotic diarrhoea.","Impairs starch digestion."],"explain":"Reduces triglyceride digestion."},{"number":3,"q":"Why can serum lipase be normal despite significant chronic pancreatic disease?","type":"SBA","options":["Endocrine islets synthesise all circulating lipase","Lipase enters blood only when bile duct is obstructed","Loss of functioning acinar tissue may reduce enzyme release","Normal lipase proves exocrine function is intact"],"answer":"C","whyOptions":["Acinar cells produce digestive enzymes.","Not required for enzyme release.","Serum lipase does not measure chronic exocrine capacity reliably.","Not true in chronic disease."],"explain":"Serum lipase does not measure chronic exocrine capacity reliably."},{"number":4,"q":"Which treatment principle explains pancreatic enzyme replacement with meals?","type":"SBA","options":["Provide enzymes only during fasting to prevent meal digestion","Use enzyme replacement to directly stimulate insulin secretion","Suppress all gastric acid permanently to regenerate acinar cells","Deliver digestive enzymes alongside food to improve luminal digestion"],"answer":"D","whyOptions":["Meal timing matters.","Does not directly replace islet function.","Acid suppression does not regenerate lost pancreas.","Supports nutrient absorption and weight gain."],"explain":"Supports nutrient absorption and weight gain."},{"number":5,"q":"Which counselling plan best addresses ongoing risks?","type":"SBA","options":["Reassure because serum lipase is normal","Recommend eliminating all fats regardless of nutritional status","Support alcohol cessation, nutrition and assessment of exocrine and glycaemic complications","Treat only the pain without assessing weight or glucose"],"answer":"C","whyOptions":["Misses chronic disease.","May worsen malnutrition.","Holistic management addresses both function and causes.","Misses major complications."],"explain":"Holistic management addresses both function and causes."},{"number":6,"q":"Which interpretation fits the results?","context":"Further tests:\nFaecal elastase (µg/g): 72  (Reference: >200)\nCT: Pancreatic calcifications and ductal irregularity  (Reference: Absent)\nHbA1c (%): 8.1  (Reference: \u003c5.7 (non-diabetic comparison))","isData":true,"type":"SBA","options":["Isolated intestinal mucosal disease with normal pancreas","Acute transient pancreatitis with preserved exocrine reserve","Isolated insulin resistance without digestive impairment","Chronic pancreatic injury with exocrine insufficiency and endocrine dysfunction"],"answer":"D","whyOptions":["Low elastase plus characteristic imaging supports pancreatic disease.","Structural and chronic functional changes argue against it.","Does not account for maldigestion and imaging.","Low elastase and calcification support chronic pancreatic insufficiency; glucose is abnormal."],"explain":"Low elastase and calcification support chronic pancreatic insufficiency; glucose is abnormal."},{"number":7,"q":"Which vitamin deficiency can produce prolonged PT in fat malabsorption?","type":"VSAQ","options":[],"answer":"Vitamin K","accepted":["vit K","K"],"explain":"Vitamin K is needed for gamma-carboxylation of several clotting factors."},{"number":8,"q":"Which islet cell produces insulin?","type":"VSAQ","options":[],"answer":"Beta cell","accepted":["beta cells","β cell","β cells","pancreatic beta cell"],"explain":"Loss of beta-cell function contributes to pancreatogenic diabetes."}]},{"id":94035,"title":"Progressive distension and altered stool calibre","core":["Colorectal Cancer"],"module":"GIT","scenario":"A 64-year-old woman has months of worsening constipation, narrower stools and intermittent rectal bleeding. She has lost weight and now has colicky lower abdominal pain, progressive distension and no passage of stool or flatus for 24 hours. Examination reveals high-pitched bowel sounds and diffuse distension.","labContext":"HR (/min): 112  (Reference: 60–100)\nBP (mmHg): 105/68  (Reference: Approx. 90–120/60–80)\nHb (g/dL): 9.6  (Reference: 12–16)\nMCV (fL): 72  (Reference: 80–100)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | GIT notes pp. 139–171; Guide p. 356","questions":[{"number":1,"q":"Which anatomical feature makes left-sided colorectal malignancy more likely to obstruct early?","type":"SBA","options":["Direct continuity with stomach prevents distal transit","Wider lumen with liquid contents","Absence of muscularis propria in left colon","Narrower lumen and more solid stool proximal to annular narrowing"],"answer":"D","whyOptions":["Incorrect anatomy.","More typical right colon and less early obstruction.","Muscularis is present.","Circumferential left-sided lesions can impede transit."],"explain":"Circumferential left-sided lesions can impede transit."},{"number":2,"q":"Which mechanism explains the initial colicky pain?","type":"SBA","options":["Continuous parietal peritoneal inflammation as the sole early mechanism","Renal capsule distension from proteinuria","Peristaltic contraction against a mechanical obstruction","Reduced smooth muscle activity without luminal narrowing"],"answer":"C","whyOptions":["Would more likely produce constant localised pain and guarding.","Does not fit GI symptoms.","Distension and contractions trigger visceral pain.","Paralytic ileus usually has a different pattern."],"explain":"Distension and contractions trigger visceral pain."},{"number":3,"q":"Which histological feature distinguishes invasive carcinoma from adenomatous dysplasia in colon?","type":"SBA","options":["Increased mucin secretion without architectural atypia","Isolated cryptitis with neutrophils","Nuclear atypia confined to mucosal glands","Malignant gland invasion through muscularis mucosae into submucosa"],"answer":"D","whyOptions":["Not diagnostic of carcinoma.","Inflammatory change.","Can be dysplasia without invasive carcinoma.","Submucosal invasion provides metastatic potential."],"explain":"Submucosal invasion provides metastatic potential."},{"number":4,"q":"What is the appropriate immediate response to suspected complete obstruction?","type":"SBA","options":["Oral bulk-forming laxative to force stool passage","Urgent surgical assessment, ABC review, IV access and nil by mouth pending evaluation","Reassure if some liquid stool previously passed","Routine outpatient screening colonoscopy preparation"],"answer":"B","whyOptions":["Can worsen obstruction.","Obstruction risks ischaemia and perforation.","Does not exclude evolving obstruction.","Unsafe in suspected complete obstruction."],"explain":"Obstruction risks ischaemia and perforation."},{"number":5,"q":"Which new sign most strongly suggests progression to peritoneal irritation?","type":"SBA","options":["Constant severe pain with involuntary guarding","Previous narrow stools","Intermittent cramps relieved between waves","Isolated chronic fatigue"],"answer":"A","whyOptions":["Possible ischaemia or perforation requires urgent escalation.","Historical clue but not acute peritonism.","Can occur in uncomplicated obstruction.","Nonspecific."],"explain":"Possible ischaemia or perforation requires urgent escalation."},{"number":6,"q":"Which interpretation best integrates structural and metabolic findings?","context":"Imaging shows dilated proximal colon, an abrupt sigmoid transition and collapsed distal bowel.\nCaecal diameter (cm): 11.5  (Reference: Generally \u003c9; increasing diameter raises risk)\nLactate (mmol/L): 3.6  (Reference: 0.5–2.0)","isData":true,"type":"SBA","options":["Isolated IBS with incidental physiological dilatation","Functional constipation with no structural transition","Mechanical large bowel obstruction with concern for threatened bowel viability","Generalised ileus with uniform small and large bowel distension"],"answer":"C","whyOptions":["Alarm features and imaging contradict this.","A transition is demonstrated.","Transition point and upstream dilatation establish obstruction; lactate raises concern but is not specific.","Distal collapse and focal transition favour mechanical obstruction."],"explain":"Transition point and upstream dilatation establish obstruction; lactate raises concern but is not specific."},{"number":7,"q":"Which embryological arterial supply serves the sigmoid colon?","type":"VSAQ","options":[],"answer":"Inferior mesenteric artery","accepted":["IMA"],"explain":"Sigmoid branches arise from the inferior mesenteric artery."},{"number":8,"q":"Which serum tumour marker can be used for baseline and follow-up but not standalone diagnosis?","type":"VSAQ","options":[],"answer":"CEA","accepted":["carcinoembryonic antigen"],"explain":"CEA may aid monitoring after confirmed colorectal cancer."}]},{"id":94036,"title":"Recurrent colic after bowel resection","core":["Renal Calculi"],"module":"Renal","scenario":"A 38-year-old man with previous ileal resection has chronic loose stools and recurrent episodes of flank pain radiating to his groin. He stopped dairy after his first stone because he thought calcium was responsible. He drinks little and works outdoors. There is no fever or haemodynamic instability.","labContext":"Creatinine (µmol/L): 103  (Reference: 60–110)\nCalcium (mmol/L): 2.36  (Reference: 2.20–2.60)\nUrine pH: 5.9  (Reference: 4.5–8.0)\nUrine blood: 2+  (Reference: Negative)","difficulty":"Hard","difficultyRating":4,"kakamed":true,"paper2Only":true,"source":"P2 KakaMed · Zain Kaka | Renal notes pp. 174–185; Guide p. 343; GIT notes malabsorption pp. 123–138","questions":[{"number":1,"q":"Which intestinal mechanism increases urinary oxalate after fat malabsorption?","type":"SBA","options":["Unabsorbed fats bind oxalate and reduce oxalate uptake","Increased dietary calcium directly increases oxalate absorption","Reduced bile salts directly increase renal oxalate synthesis","Unabsorbed fatty acids bind calcium, leaving soluble oxalate available for absorption"],"answer":"D","whyOptions":["Would reduce urinary oxalate.","Calcium can bind oxalate in gut.","Not principal mechanism.","Enteric hyperoxaluria results from reduced intestinal calcium binding of oxalate."],"explain":"Enteric hyperoxaluria results from reduced intestinal calcium binding of oxalate."},{"number":2,"q":"Why can severe calcium restriction worsen stone risk?","type":"SBA","options":["Less luminal calcium is available to bind dietary oxalate","Calcium restriction increases insoluble oxalate binding","Low calcium always increases serum calcium","Low calcium directly activates bacterial urease"],"answer":"A","whyOptions":["Increases absorption of soluble oxalate.","Opposite effect.","Not reliable.","Not related."],"explain":"Increases absorption of soluble oxalate."},{"number":3,"q":"Which drug class can reduce urinary calcium in selected patients with persistent hypercalciuria?","type":"SBA","options":["Carbonic anhydrase inhibitors","Thiazide diuretics","Osmotic diuretics","Loop diuretics"],"answer":"B","whyOptions":["May increase calcium phosphate stone risk.","Inhibit distal Na-Cl cotransporter and reduce urinary calcium excretion; clinical indication requires assessment.","Not characteristic long-term prevention.","Usually increase urinary calcium excretion."],"explain":"Inhibit distal Na-Cl cotransporter and reduce urinary calcium excretion; clinical indication requires assessment."},{"number":4,"q":"Which consequence of chronic diarrhoea may reduce inhibition of calcium stone formation?","type":"SBA","options":["Increased serum bicarbonate necessarily lowers urine citrate","Diarrhoea directly prevents supersaturation","Metabolic acidosis can reduce urinary citrate","Increased urinary citrate raises free calcium"],"answer":"C","whyOptions":["Alkali may increase citrate excretion.","Low urine volume raises supersaturation.","Hypocitraturia reduces calcium complexation.","Citrate complexes calcium."],"explain":"Hypocitraturia reduces calcium complexation."},{"number":5,"q":"Which prevention plan is most appropriate?","type":"SBA","options":["Use antibiotics continuously despite sterile urine","Recommend high-dose vitamin C as routine prevention","Increase feasible fluid intake, normal dietary calcium with meals and tailored nutrition review","Eliminate calcium indefinitely and restrict fluid"],"answer":"C","whyOptions":["Not appropriate for metabolic stones.","May increase oxalate load.","Addresses low urine volume, enteric oxalate uptake and practical barriers.","Both may worsen risk."],"explain":"Addresses low urine volume, enteric oxalate uptake and practical barriers."},{"number":6,"q":"Which interpretation best explains recurrence?","context":"Metabolic assessment:\n24 h urine volume (L): 0.9  (Reference: Target often ≥2–2.5 for prevention)\nUrine oxalate (mmol/day): 0.68  (Reference: Approx. \u003c0.45 (lab-dependent))\nStone analysis: Calcium oxalate  (Reference: No stone)","isData":true,"type":"SBA","options":["Cystine precipitation due to amino acid transporter defect","Uric acid precipitation from isolated low urine pH","Calcium oxalate supersaturation due to enteric hyperoxaluria and low urine volume","Struvite precipitation due to alkaline urease infection"],"answer":"C","whyOptions":["Stone composition does not support it.","Composition is calcium oxalate.","Both increase supersaturation despite normal serum calcium.","No such evidence."],"explain":"Both increase supersaturation despite normal serum calcium."},{"number":7,"q":"Name the excess urinary excretion of oxalate caused by intestinal malabsorption.","type":"VSAQ","options":[],"answer":"Enteric hyperoxaluria","accepted":["hyperoxaluria"],"explain":"Fat malabsorption can increase intestinal oxalate uptake."},{"number":8,"q":"Which renal tubular segment is the target of the thiazide-sensitive sodium–chloride cotransporter?","type":"VSAQ","options":[],"answer":"Distal convoluted tubule","accepted":["DCT","distal tubule"],"explain":"Thiazides inhibit NCC in the distal convoluted tubule."}]}];
